'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["hr"]={"g-flurpruefung":["Što uključuje vizualni i funkcionalni pregled prije početka rada?","Prije prve misije dana.","Provjerite samo razinu goriva i boju vozila.","Provjerite kočnice, upravljač, vilice, gume i sigurnosne uređaje prema uputama za uporabu.","Provedite probnu vožnju s podignutim teretom.","Dnevni pregled uključuje dijelove i funkcije bitne za sigurnost prema uputama za uporabu."],"g-rueckhalt":["Kako se nosite s postojećim sigurnosnim sustavom za vozača?","Viljuškar ima obvezni sigurnosni sustav.","Pravilno ga koristite tijekom vožnje.","Koristite samo na neravnim podovima.","Isključite ga za kratka putovanja.","Predviđeni sigurnosni sustavi moraju se koristiti u skladu s uputama proizvođača; pružaju posebnu zaštitu u slučaju preokreta."],"g-mangelmelden":["Što vrijedi za viličar s oštećenom vilicom?","Prilikom provjere primijetili ste jasno savijeni zupci.","Ako je moguće, rasporedite teret na druge zupce.","Vozite samo lake terete do sljedećeg servisa.","Ne koristite viličar i prijavite kvar odgovornoj osobi.","Oštećena oprema za rukovanje teretom može otkazati; Sigurnosni kvarovi zahtijevaju isključivanje do razjašnjenja."],"g-einweisung":["Prebacujete se na viličar s drugačijim kontrolama. Što je potrebno prije upotrebe?","Operacija se razlikuje od vašeg prethodnog vozila.","Upute vezane uz uređaj i pridržavanje uputa za uporabu.","Uvijek je dovoljno kratko objašnjenje neumiješanog kolege.","Nema dodatnih informacija ako imate dozvolu za viličar.","Opća kvalifikacija ne zamjenjuje potrebne upute o stvarno korištenom uređaju."],"g-anbaugeraet":["Trebali biste koristiti prilog. Što prvo provjerite?","Novi dio opreme mijenja način preuzimanja tereta.","Odgovara li priključak homologaciji vozila i dopuštenom opterećenju.","Samo može li se uređaj vizualno pričvrstiti.","Može li se priključak ugraditi bez dokumentacije.","Priključci mogu promijeniti preostali kapacitet opterećenja i centar opterećenja; Odobrenja i podaci o nosivosti moraju se provjeriti."],"g-diagramm":["Zašto vam je potreban dijagram nosivosti?","Prisutan je veliki teret s težištem daleko prema van.","Za određivanje najkraćeg puta.","Za procjenu najvećeg dopuštenog opterećenja ovisno o visini dizanja i središtu opterećenja.","Za određivanje kapaciteta spremnika.","Dopuštena opterećenja ovise, između ostalog, o udaljenosti središta tereta i visini dizanja."],"g-lastschwerpunkt":["Što se obično događa kada se težište pomakne dalje naprijed?","Dugi teret strši daleko ispred vilica.","Dopuštena nosivost se može smanjiti.","Nosivost uvijek raste.","Udaljenost nema utjecaja na moment prevrtanja.","Veća udaljenost od središta opterećenja povećava moment prevrtanja i može smanjiti dopuštenu nosivost."],"g-gabelabstand":["Kako bi vilice trebale pokupiti odgovarajuću paletu?","Želite podići ravnomjerno natovarenu paletu.","Sa zupcima što bliže i samo na jednom uglu.","S tako velikim razmakom da se paleta prevrne u stranu.","S odgovarajućim razmakom između zubaca i dovoljnim podvozjem i potpornom površinom.","Teret mora biti poduprt sigurno i što je moguće ravnomjernije preko vilica."],"g-schieflast":["Teret je nestabilno složen. Što je ispravno?","Kartonske kutije mogu pasti kada se podignu.","Počnite polako; naboj se sam stabilizira.","Prije podizanja tereta, osigurajte ga dovoljno ili ga dajte ponovno sastaviti.","Podignite teret iznad visine glave tako da vam ne smeta.","Rasuti ili nestabilni teret može pasti i ugroziti ljude; prvo provedite sigurnosne mjere."],"g-personen":["Može li se čovjek podići na obične vilice?","Kolega želi doći do svjetla.","Da, ako kolega nosi kacigu.","Ne, osobe mogu koristiti samo određene i dopuštene objekte u skladu s posebnim uvjetima.","Da, ako se pristupi samo maloj visini.","Normalne vilice nisu osobna radna platforma; Prijevoz i podizanje ljudi podliježe posebnim zahtjevima."],"g-transporthoehe":["Kako obično transportirate paletu?","Cesta je čista i ravna.","S podignutim teretom samo onoliko koliko je potrebno iu skladu s uputama za uporabu.","S teretom podignutim što je više moguće da se bolje vidi.","S podiznim jarbolom snažno nagnutim prema naprijed, bez obzira na opterećenje.","Nizak transportni položaj smanjuje rizik od prevrtanja i sudara; Upute za uređaj su odlučujuće."],"g-kurvenfahrt":["Zašto je brzo skretanje viličarom opasno?","Želite brzo izaći s uske staze.","Jer samo brže prazni bateriju.","Zato što viličar automatski bolje upravlja.","Budući da bočne sile utječu na stabilnost i mogu dovesti do prevrtanja.","U zavojima dolaze do izražaja dodatne sile; brzina mora biti prilagođena opterećenju i uvjetima."],"g-ladebruecke":["Što provjeravate prije vožnje na utovarni most?","Trebao bi se voziti u kamionu.","Samo izgleda li staza dovoljno široka.","Nosivost, siguran oslonac i zaštita od pomicanja kao i osiguranje vozila.","Samo je li rasvjeta uključena.","Utovarni mostovi i vozila moraju biti osigurani od pomicanja i prikladni za teret."],"g-fussgaenger":["Kako se ponašati na zbunjujućem raskrižju s pješacima?","Vizualne veze su ograničene.","Vozite primjerenom brzinom, po potrebi se zaustavite i osigurajte sigurnu preglednost.","Uvijek zahtijevajte pravo prvenstva kada nosite teret.","Samo zatrubi i nastavi voziti.","Pješaci imaju posebne potrebe zaštite; Brzina, preglednost i komunikacija moraju biti prilagođeni prometnom pravcu."],"g-batterieladen":["Na što treba obratiti posebnu pozornost prilikom punjenja pogonske baterije?","Koristi se stanica za punjenje baterija.","Mjesto punjenja može se odabrati neovisno o uputama proizvođača.","Otvoreni plamen je dopušten sve dok kamion miruje.","Prikladan prostor za utovar, dovoljna ventilacija i specifikacije proizvođača kao i zaštita od požara i eksplozije.","Tijekom punjenja mogu nastati opasnosti od električne energije, plinova i kemikalija; moraju se pridržavati predviđenih zaštitnih mjera."],"h-beauftragt":["Pod kojim uvjetima smijete samostalno upravljati dizalicom?","U tvrtki biste trebali koristiti radnu platformu.","Ako imate vozačku dozvolu za automobil.","Ako ste prikladni, upućeni ili kvalificirani i ovlašteni od strane poslodavca.","Ako ste ikada vidjeli radnu platformu.","Poslodavac mora osigurati prikladnost, kvalifikacije i zadatke u skladu s operativnim zahtjevima."],"h-vorpruefung":["Što treba provjeriti prije početka rada s dizalicom?","Pozornica je preko noći bila vani.","Vizualno i funkcionalno ispitivanje prema uputama proizvođača uključujući sigurnosne uređaje.","Samo boja i starost pozornice.","Je li radni materijal već na platformi.","Prije uporabe potrebno je provjeriti stroj, kontrole, hitne funkcije i vidljiva oštećenja u skladu s uputama za uporabu."],"h-tragfaehigkeit":["Koji podatak određuje dopušteno opterećenje radne košare?","Dvije osobe bi željele ponijeti dodatni alat sa sobom.","Ljudi mogu slobodno procijeniti dopuštenu ukupnu težinu.","Računa se samo težina najteže osobe.","Ne smije se prekoračiti specifikacija nosivosti za ljude, alate i materijal.","Nazivno opterećenje odnosi se na ukupno dopušteno opterećenje, uključujući sav materijal koji se prevozi."],"h-untergrund":["O čemu razmišljate prije postavljanja pozornice s potporama?","Radite u blizini ispunjenog područja.","Samo na dohvat grane.","Provjerite nosivost i ravnost podloge kao i odgovarajuću podlogu prema uputama.","Na najmanji mogući broj produženih oslonaca.","Nedovoljno tlo ili nepravilna potpora mogu dovesti do gubitka stabilnosti."],"h-wind":["Postaje jak vjetar. Kako to učiniti?","Naći ćete se s pozornicom na otvorenom.","Pridržavajte se ograničenja proizvođača i ako su prekoračena, zaustavite rad ili sigurno spustite košaru.","Proširite platformu što je više moguće kako bi bila stabilnija.","Reagirajte samo ako labavi predmeti padnu.","Uvjeti vjetra koje dopušta proizvođač su ograničenja uporabe; Vjetar može stvoriti opasne dodatne sile."],"h-strom":["Morate raditi u blizini dalekovoda. Što je presudno?","Linija pod naponom je u radnom području.","Kaciga zamjenjuje održavanje sigurnog razmaka.","Samo izolirajte košaru i radite bez koordinacije.","Razjasnite opasno područje i osigurajte potrebne zaštitne udaljenosti ili druge odgovarajuće mjere.","Električni bljesak je također moguć bez izravnog kontakta; Prije početka rada potrebno je odrediti potrebne mjere zaštite."],"h-notablass":["Zašto je potrebno poznavati postupak hitnog spuštanja?","Moguć je kvar normalne kontrole.","Tako da je u slučaju kvara moguće sigurno spašavanje prema uređaju.","Tako da uređaj radi brže u normalnom radu.","Za zamjenu redovnog testiranja.","Koncepti upravljanja u slučaju nužde, spuštanja u nuždi i spašavanja moraju biti poznati i funkcionalni prije uporabe."],"h-gelaender":["Kako postići dodatnu visinu u radnoj košari?","Točka montaže je izvan vašeg dosega.","Popnite se na ogradu koša.","Stavite dasku na ogradu.","Koristite odgovarajuću platformu s dovoljnom radnom visinom; ne penjati se na ograde.","Penjanje na ogradu ili improvizirana uzvišenja ugrožava zaštitu od pada."],"h-psaga":["Koji se zahtjevi odnose na osobnu opremu za zaštitu od pada?","Koristite radnu platformu za koju je predviđen sigurnosni sustav.","Bilo koja sidrišna točka izvan košare uvijek je dovoljna.","Poštujte procjenu rizika, informacije o proizvođaču i prikladne točke za sidrenje.","Nemojte koristiti nikakvo osiguranje ako košara ima ogradu.","Je li i koja OZO potrebna određuje se procjenom rizika, konstrukcijom pozornice i uputama za rad."],"h-verfahren":["Može li se pozornica pomicati s podignutom platformom?","Radno mjesto je udaljeno nekoliko metara.","Samo ako model i uvjeti rada to dopuštaju prema uputama proizvođača.","Uvijek, dok se svi drže.","Ne, nikada bez obzira na dizajn i odobrenje proizvođača.","Kretanje u podignutom položaju ovisi o uređaju i dopušteno je samo unutar odobrenih radnih uvjeta."],"h-kollision":["Što je potrebno organizirati pri radu u blizini dizalica ili drugih strojeva?","Pokretni dijelovi mogu dospjeti u radnu košaru.","Ništa; radna košara je uvijek vidljiva.","Radnu košaru uvijek vozite preko drugih strojeva.","Koordinirajte radna područja kako biste izbjegli sudare ili priklještenja.","Simultani rad stroja zahtijeva koordinirane radne procese i zaštitu od sudara ili ometanja."],"h-einstieg":["Kako ulazite ili izlazite iz radne košare?","Dolazite do košare na razini tla.","Popnite se preko vanjske ograde.","Preko predviđenog pristupa u sigurnom položaju prema uputama za uporabu.","Putem ljestava postavljenih pokraj njih s izvučenom granom.","Moraju se pridržavati predviđenog pristupa i uputa proizvođača; Nekontrolirano penjanje preko predstavlja opasnost od pada."],"h-defekt":["Uređaj za hitno zaustavljanje ne radi. sta to radis","Kvar ćete otkriti tijekom pregleda.","Ne koristite platformu i prijavite kvar.","Nastavite s radom ako normalne kontrole rade.","Zalijepite prekidač tako da ga nitko ne koristi.","Kvar sigurnosnog uređaja je kvar koji je bitan za sigurnost i sprječava siguran rad."],"h-sicht":["Pokret u vožnji ne može se vidjeti zbog prepreke. Kako to činiš?","Trebali biste premjestiti pokretnu pozornicu.","Vozite polako bez vidljivosti.","Oslonite se samo na indikator udaljenosti.","Zaustavite kretanje i osigurajte vidljivost ili sigurnu poduku prema uputama za rad.","Prije zahvata potrebno je sigurno pregledati ljude, prepreke i prometne puteve."],"h-rettung":["Što uključuje planiranje postavljanja kada se radi na većim visinama?","Pozornica se koristi u udaljenom području.","Samo planirano trajanje rada.","Prikladan koncept spašavanja s pristupačnim, obučenim ljudima i postupcima spuštanja u hitnim slučajevima.","Pretpostavka da će vatrogasci svaki problem odmah riješiti.","Učinkovito spašavanje mora biti organizirano unaprijed, čak i ako normalne kontrole zakažu."],"k-befaehigung":["Što je potrebno za samostalno upravljanje dizalicom?","Novi zaposlenik trebao bi preuzeti poslove dizalice.","Prikladnost i potrebne kvalifikacije, poduka i pripadajući zadatak.","Dovoljna je vozačka dozvola za automobil.","Gledanje jednom je dovoljno.","Rad s dizalicom smije se povjeriti samo kvalificiranim i ovlaštenim osobama; Upute za opremu dio su toga."],"k-funktionspruefung":["Što je potrebno za provjeru dizalice prije početka smjene?","Preuzimate sobnu dizalicu.","Samo pročitajte vrijeme rada na natpisnoj pločici.","Provjerite sigurnosno važne funkcije i vidljive nedostatke prema uputama za uporabu.","Ispitajte dizalicu s maksimalnim opterećenjem bez provjere.","Obavezna radna kontrola služi za prepoznavanje opasnih nedostataka u ranoj fazi."],"k-traglast":["Koje je značenje dopuštene nosivosti?","Teret treba podići.","To je neobvezujuća preporuka.","Primjenjuje se samo kada je kuka potpuno uvučena.","Dopuštena nosivost za odgovarajuće uvjete rada ne smije se prekoračiti.","Dopuštena opterećenja za pojedine vrste dizalica mogu ovisiti o polumjeru, položaju kraka i naoružanju."],"k-personen":["Što se odnosi na ljude pod visećim teretom?","Teret se pomiče preko radnog područja.","Opasno područje mora biti slobodno; nitko ne smije kročiti ispod obješenog tereta.","Kaciga vam omogućuje da ostanete izravno ispod nje.","Kratki prijelazi dopušteni su ako se dizalica kreće sporo.","Viseći tereti predstavljaju opasnost od pada i prignječenja; Ljudi se moraju držati podalje od opasnog područja."],"k-signale":["Ne možete vidjeti napadača i dobivate kontradiktorne signale. sta to radis","Komunikacija je nejasna.","Nastavite posljednju naredbu vožnje.","Zaustavite pokret i jasno razjasnite komunikaciju.","Spustite teret brže, bez savjetovanja.","Sigurno kretanje tereta zahtijeva jasne signale i jasnu komunikaciju."],"k-sicht":["Tko će pružiti potporu tijekom transporta ako operater dizalice ne može u potpunosti vidjeti putanju tereta?","Stup hodnika zaklanja put.","Osoba koja slučajno prođe bez prethodnog dogovora.","nitko; bitna je samo udica.","Prikladna, upućena osoba s jasno dogovorenim razumijevanjem.","Ako put tereta nije vidljiv, potrebna je odgovarajuća uputa ili drugo sigurno rješenje."],"k-ruck":["Zašto treba izbjegavati trzajne pokrete dizalice?","Teški teret počinje se njihati.","Oni stvaraju dodatna dinamička naprezanja i mogu destabilizirati opterećenje.","Oni u osnovi smanjuju bilo kakvo kretanje njihala.","Uvijek povećavaju nazivnu nosivost.","Sile ubrzanja i kočenja povećavaju opterećenje dizalice i remena."],"k-sperrbereich":["Što trebate provjeriti prije ljuljanja tereta u zajedničkom prostoru?","Ostali zaposlenici rade u blizini.","Odgovara li opterećenje vizualno dizalici.","Da li je opasno područje osigurano i da li ljudi nisu u opasnosti.","Može li se teret nositi što više iznad svih.","Okretne i teretne staze ne smiju biti nezaštićene osobe."],"k-stuetzen":["Što je ključno za pokretnu dizalicu s potpornim nosačima?","Dizalica je postavljena na djelomično nasuto tlo.","Samo širina ceste.","Boja potpornih ploča.","Nosivo postolje kao i oslonac i raspodjela opterećenja prema uputama za ugradnju i proizvođačima.","Instalacija ima značajan utjecaj na stabilnost, posebno u promjenjivim uvjetima tla."],"k-wetter":["Nalet vjetra uzrokuje znatno ljuljanje tereta. Što je ispravno?","Radite na otvorenom.","Sigurno zaustavite kretanje i pridržavajte se dopuštenih radnih uvjeta.","Brzo ubrzajte pokret.","Nastavite s podizanjem tereta unatoč prekoračenju ograničenja proizvođača.","Vjetar i njihanje mogu destabilizirati teret i dizalicu; Moraju se poštovati ograničenja primjene."],"k-freileitung":["Što vrijedi pri korištenju dizalica u blizini nadzemnih električnih vodova?","Grana ili teret mogli bi se približiti liniji.","Kod nevodljivog opterećenja razmaci nisu važni.","Prije početka rada s odgovornim osobama razjasnite opasno područje i potrebne mjere zaštite.","Oslonite se samo na reakciju rukovatelja dizalice.","Postoje opasnosti od kontakta i preskoka napona; potrebne su sigurne zaštitne udaljenosti ili druge mjere."],"k-sichern":["Što radite prije nego napustite kran?","Rad je prekinut.","Pustite teret da visi.","Ostavite dizalicu bez nadzora dok pogon radi.","Sigurno spustite teret i osigurajte dizalicu prema uputama za rad.","Viseći tereti ne smiju se ostaviti nekontroliranim; Dizalica i teret moraju biti sigurno parkirani."],"k-lastanschlag":["Kako znati je li korišteni remen prikladan?","Teret treba podići pomoću trake za podizanje.","Što se tiče označavanja, nosivosti, stanja i prikladnosti za vrstu priključka.","Samo po boji trake za podizanje.","Jer je već jučer korišten.","Nosivost i stanje moraju biti dovoljni, uzimajući u obzir uvjete pričvršćenja."],"k-stopp":["Osoba neočekivano ulazi na put tereta. sta to radis","Dizalica trenutno pomiče teret.","Odmah zaustavite kretanje i oslobodite opasno područje.","Samo dajte znak upozorenja i nastavite voziti.","Podignite teret više i vozite preko njega.","Ljudi moraju biti zaštićeni od pomicanja tereta; Ako postoji neposredna opasnost, kretanje se mora zaustaviti."],"k-neuerkran":["Dobit ćete dizalicu s nepoznatom kontrolom. Što je ispravno?","Kontrole su drugačije nego prije.","Pokušajte s uobičajenim ključevima ako sumnjate.","Dopustite nekom drugom bez obuke da vozi naprijed.","Primite potrebne upute za uređaj prije samostalne uporabe.","Čak i iskusni rukovatelji dizalicama trebaju znanje o specifičnim kontrolama koje se koriste, zaštitnim uređajima i ograničenjima."],"a-kennzeichnung":["Kako znati dopuštenu nosivost remena?","Želite odabrati remen.","Miris materijala.","Na odgovarajućoj, čitljivoj oznaci nosivosti i podacima proizvođača.","O duljini vremena skladištenja.","Dopuštena nosivost određena je označavanjem i radnim uvjetima."],"a-sichtpruefung":["Primjećujete jasan rez na remenu za podizanje. Kako to činiš?","Bend bi trebao nositi teret.","Nemojte koristiti traku i poslati je na testiranje ili odbacivanje.","Prekrijte rez trakom.","Koristite ga samo za posebno mala opterećenja.","Oštećene tekstilne priveznice mogu pokvariti i moraju se ocijeniti prema kriterijima za odbacivanje."],"a-neigungswinkel":["Što se događa ako je kut nagiba užeta remena veći od okomice?","Vješalica s dvije niti više se širi.","Sile užeta uvijek se smanjuju.","Sile pramenova ostaju iste.","Sile u nitima se povećavaju; Moraju se poštovati dopušteni kutovi i nosivosti.","Kako se širina povećava, vlačna sila po potpornoj niti raste."],"a-schwerpunkt":["Zašto trebate znati težište tereta?","Opterećenje se nakuplja neravnomjerno.","Kako bi teret ostao stabilan prilikom podizanja i ne bi se nekontrolirano prevrnuo.","Za odabir boje remena.","Kako bi se teret mogao brže okretati.","Nepovoljne točke pričvršćivanja ili položaj težišta mogu dovesti do prevrtanja, klizanja ili nagnutih padina."],"a-kantenschutz":["Traka za podizanje leži na oštrom rubu komponente. Što treba učiniti?","Komponentu treba podići.","Brzo podignite teret prije nego se pojas ošteti.","Koristite odgovarajuću zaštitu rubova i provjerite vrstu pričvršćenja.","Površinu tereta čistite samo krpom.","Oštri rubovi mogu oštetiti noseća vlakna; oprema za vrpcu mora biti zaštićena na odgovarajući način."],"a-haken":["Na što obraćate pozornost prilikom pričvršćivanja remena?","Koristite kuku za teret.","Postavite remen sa strane vrha udice.","Držite sigurnosni poklopac trajno otvorenim.","Stavite kuku kako je predviđeno u bazu kuke i obratite pažnju na sigurnosne uređaje.","Nedopušteno opterećenje vrha udice i neučvršćenje mogu dovesti do njenog otkačavanja."],"a-knoten":["Možete li čvorom skratiti remen za podizanje koji je predug?","Stop duljina ne odgovara.","Ne; Koristite samo prikladnu, odobrenu vrstu remena ili odgovarajuću opremu za remen.","Da, ako je čvor vrlo čvrsto zategnut.","Da, sve dok teret trenutno miruje.","Čvorovi mogu značajno oslabiti tekstilne priveznice i nisu dopuštene improvizirane prilagodbe duljine."],"a-probehub":["Zašto se teret u početku pažljivo podiže?","Želite prevoziti sigurno.","Tako da može što brže putovati na posao.","Za provjeru položaja remena, stabilnosti i težišta.","Budući da se nosivost automatski povećava.","Kontrolirani prvi hod pomaže otkriti pogrešna zaustavljanja i nestabilne položaje tereta."],"a-lastweg":["Gdje ljudi smiju boraviti dok se teret prevozi?","Teret se pomiče dizalicom.","Izravno ispod tereta sa zaštitnom kacigom.","Na teretu ako mogu izdržati.","Izvan opasnog područja i ne ispod visećih tereta.","Čak i uz pažljivo pričvršćivanje, još uvijek postoje opasnosti od pada ili ljuljanja tereta."],"a-haende":["Kako izbjeći ozljede od nagnječenja tijekom odvikavanja?","Teret se približava površini potpore.","Ruke i noge držite podalje od područja gnječenja i koristite odgovarajuća pomagala.","Držite teret golom rukom.","Stanite između tereta i zida kako biste ispravili položaj.","Opasna mjesta priklještenja nastaju između tereta i potpore."],"a-vierstraenge":["Što se odnosi na raspodjelu opterećenja na četverokrakom ovjesu bez kompenzacije opterećenja?","Priložen je kruti teret.","Sve četiri niti neizbježno nose isti iznos.","Bez dokaza o ravnomjernoj raspodjeli, nosivost se ne može koristiti kao opća procjena za četiri jednako opterećene niti.","Kut nagiba tada nije bitan.","Kod krutih opterećenja moguće je nejednako opterećenje; Dizajn i dopuštena nosivost moraju to uzeti u obzir."],"a-chemikalien":["Što vrijedi pri korištenju tekstilnih remena u kontaktu s kemikalijama?","Radite s nepoznatom tekućinom.","Boja trake pouzdano pokazuje njezinu trajnost.","Svaka tekstilna traka je otporna na sve kemikalije.","Provjerite trajnost i informacije o proizvođaču; Nemojte koristiti neprikladna sredstva.","Kemikalije mogu napasti remen i neprimjetno smanjiti njihovu nosivost."],"a-aufbewahrung":["Kako se naramenice čuvaju nakon upotrebe?","Misija je gotova.","Čisto, suho i zaštićeno od oštećenja prema specifikacijama proizvođača.","Zaglavljen na tlu pod nezaštićenim teretom.","Na bilo koju oštru udicu na otvorenom.","Odgovarajuće skladištenje sprječava prerano trošenje i olakšava vizualni pregled."],"a-auswahl":["Na što treba obratiti posebnu pozornost kada radite s osjetljivim ili oštrim teretom?","Treba premjestiti obojenu komponentu stroja.","Samo brzina transporta.","Prikladne priveznice i zaštitne mjere za teretnu površinu i rubove.","Bez obzira na opterećenje, uvijek ista čelična sajla.","Vrsta pričvršćenja i materijal moraju odgovarati geometriji, površini i opasnosti."],"a-abstimmung":["Kranist nema pogled na vas. Kako dajete upute?","Dodijeljen si kao napadač.","Mašete po volji dok ne počne pokret.","Samo jedan poziv nazoveš i odeš.","Preko jasno dogovorenih znakova ili druge pouzdane komunikacije.","Napadači i kranisti moraju jasno komunicirati; Ako je nejasno, kretanje se mora zaustaviti."],"b-qualifikation":["Što je potrebno osobi za sigurno upravljanje hidrauličkim bagerom tijekom rada?","Radove na gradilištu trebala bi preuzeti nova osoba.","Odgovarajuće kvalifikacije, upute vezane uz uređaj i traženi zadatak.","Samo vozačka dozvola za automobil.","Samo kratko promatranje operacije.","Poslodavac mora osigurati potrebne kvalifikacije i uputiti operatera na odgovarajući način za zadatak."],"b-pruefung":["Što je uključeno u dnevni pregled stroja?","Preuzimaš bager.","Provjerite boju laka i presvlake sjedala.","Vizualni pregled i funkcionalna ispitivanja u skladu s uputama za uporabu, na primjer curenja i oštećenja.","Pomičite granu punom brzinom dok se ne zaustavi.","Oštećenje hidraulike, šasije i sigurnosnih uređaja može dovesti do ozbiljnih nesreća."],"b-leitungen":["Što treba znati o podzemnim cijevima prije iskopa?","Trebao bi iskopati jarak.","Samo okvirna dubina planirane jame za iskop.","Dovoljna je boja nadzemnih oznaka.","Pojasnite lokaciju mogućih vodova i odredite prikladne mjere sigurnosti i istraživanja.","Cijevi za struju, plin ili vodu mogu imati posljedice opasne po život ako su oštećene."],"b-schwenkbereich":["Kako štitite ljude u zoni okretanja bagera?","Granom podižete materijal.","Ogradite ili osigurajte opasno područje i držite ljude podalje.","Prije okretanja, polako pomičite lopatu.","Vozite preko područja iznad glava.","Zakretna nadgradnja i radna oprema stvaraju opasnost od prignječenja i udara."],"b-boeschung":["Što je važno kada se radi blizu ruba jame za iskop?","Bager stoji na utvrđenom ili nasutom terenu.","Sama dubina kopanja određuje dopušteni položaj.","Obratiti pozornost na nosivost i osiguranje ruba te potrebne udaljenosti prema procjeni rizika.","Vozite što bliže rubu kako biste uštedjeli domet.","Ako nema dovoljno slobodnog prostora ili stabilnog tla, nasip može otpasti i stroj može pasti."],"b-standsicherheit":["Zašto su nagib i teren ključni za korištenje?","Gradilište je na padini.","Stroj je jednako stabilan na bilo kojoj površini.","Donji postroj na gusjenicama eliminira svaki rizik od prevrtanja.","Neravnine i padine mogu utjecati na stabilnost; Pridržavajte se ograničenja primjene.","Stabilnost i sigurnost prevrtanja ovisi o podu, opremi, opterećenju i položaju stroja."],"b-wechselgeraet":["Što provjeravate nakon izmjene žlice bagera pomoću brze spojnice?","Instaliran je novi dodatak.","Je li ispravno zaključan i osiguran prema uputama za uporabu.","Samo odgovara li boja lopate.","Da li hidraulika radi što tiše.","Neispravne brave mogu uzrokovati pad dodataka."],"b-heben":["Na što treba obratiti pozornost pri dizanju tereta koji slobodno visi bagerom?","Bager se koristi za operacije dizanja.","Presudna je samo uobičajena sila kopanja.","Obratite pažnju na dopušteno opterećenje dizanja, prikladne točke pričvršćenja i propisane zaštitne naprave.","Teret se može zakačiti na zupce kante.","Podizanje je dopušteno samo u predviđenim radnim uvjetima s odgovarajućom opremom."],"b-rueckwaerts":["Moraš u rikverc, ali ne vidiš stazu. Što je ispravno?","Ostali radnici su u blizini.","Vozite oprezno bez vidljivosti.","Samo zatrubi i nastavi voziti.","Zaustavite se, osigurajte vidljivost i opasno područje ili organizirajte odgovarajuće upute.","Vožnja unatrag ne smije ugrožavati ljude; ograničena vidljivost zahtijeva dodatne mjere."],"b-kabel":["Grana bi se mogla približiti nadzemnom dalekovodu. sta to radis","Radite na tijesnom gradilištu.","Prethodno s odgovornima razjasnite opasno područje i odgovarajuće zaštitne mjere.","Zanemarite liniju ako je krak obojen.","Ruku pomičite samo posebno brzo.","Električne opasnosti proizlaze iz kontakta i bljeska; potrebne su sigurne udaljenosti i mjere zaštite."],"b-verlassen":["Kako parkirati bager prije odlaska?","Odmori se.","Ostavite granu da slobodno pluta.","Sigurno odložite radnu opremu i osigurajte stroj od pomicanja i neovlaštene uporabe.","Ostavite motor upaljen, a kabinu otvorenu.","Spuštena radna oprema i zaštita od nenamjernog pomicanja smanjuju rizik od nezgoda."],"b-hydraulik":["Primijetili ste hidrauličko ulje pod visokim pritiskom na oštećenom vodu. Što je ispravno?","Linija curi.","Rukom osjetite curenje.","Pričvrstite novu stezaljku pod pritiskom.","Sigurno isključite stroj, dopustite da se tlak smanji i dogovorite popravke koje će izvršiti ovlašteno stručno osoblje.","Hidraulička tekućina pod visokim pritiskom može uzrokovati ozbiljne ozljede; nikad ne provjeravajte curenje rukom."],"b-unterbau":["Koja je opasnost od vožnje po nestabilnim površinama?","Tlo je mekano nakon kiše.","Stroj može potonuti, skliznuti ili se prevrnuti.","Pogon automatski postaje širi.","To čini područje okretanja sigurnijim.","Nedovoljna nosivost može znatno narušiti stabilnost i sigurnost vožnje."],"b-arbeitsgeraet":["Može li netko raditi ispod podignute opreme?","Osoba želi nešto kontrolirati pod lopatom.","Da, kada motor radi u leru.","Ne, ne bez potrebne sigurne potpore i osiguranja radne opreme.","Da, ako osoba nosi zaštitnu kacigu.","Hidraulička oprema može potonuti; Radovi na održavanju zahtijevaju sigurnu radnu opremu."],"b-geraeteart":["Prebacujete se s hidrauličnog bagera na utovarivač na kotačima. Što je potrebno?","Rad i kretanje su različiti.","Samo ista obuća.","Probna vožnja bez uputa.","Kvalifikacija ili instrukcija potrebna za novu vrstu stroja.","Kvalifikacija mora odgovarati vrsti stroja koji se koristi i specifičnim radnim zahtjevima."],"g-neigung":["Vozite natovareni viličar na uzbrdici. Što je važno?","Ruta ima jasan uspon.","Uvijek vodite teret nizbrdo, čak i ako je težak.","Vodite teret uzbrdo i pridržavajte se operativnih smjernica za vožnju na usponima.","Bez obzira na smjer vožnje, podignite vilicu do maksimuma.","Na usponima i nizbrdicama teret uvijek treba nositi uzbrdo; Morate se pridržavati uputa za uporabu i vozila."],"g-gabelabsenken":["Zašto vilica mora biti spuštena prilikom parkiranja?","Viljuškar je parkiran za pauzu.","Tako da se drugi mogu koristiti rašljama za penjanje.","Tako da vilica ostane vidljivija iz daljine.","Kako podizanje tereta ne bi predstavljalo nepotreban rizik od spoticanja ili ozljeda.","Spušteni uređaji za rukovanje teretom smanjuju rizik od nezgoda zbog izbočenih ili neosiguranih vilica."],"g-fahrerwechsel":["Kolega bi želio posuditi viličar. Što mora biti prisutno?","Kolega od vas ima samo usmeno dopuštenje.","Mora imati potrebne kvalifikacije i operativni mandat.","Vaš vlastiti zadatak automatski se odnosi i na njega.","Za svaki posao dovoljna je vozačka dozvola za privatni automobil.","Neovisno vodstvo povezano je s osobnom podobnošću, obukom, kvalifikacijama i operativnim zadatkom."],"g-ladungssicherung":["Paleta sadrži labave, naslagane kutije. Što je ispravno?","Kartonska kutija može pasti tijekom vožnje.","Osigurajte teret od klizanja i pada prije transporta.","Vozite polako samo na posebno neravnom terenu.","Nadoknadite labave kutije višim položajem vilice.","Teret mora biti stabilan i osiguran od pada prije transporta viličarom."],"g-bodenbelastung":["Pred vama je deka ograničene nosivosti. Kako se odlučujete?","Ruta vodi preko srednje razine.","Samo obratite pozornost na težinu kamiona bez tereta.","Pojasnite dopušteno opterećenje poda za viličare i terete.","Vozite zamahom tako da strop bude pod opterećenjem kraće vrijeme.","Ono što je relevantno je ukupno stvarno opterećenje na području, uključujući vozilo, opterećenje i dinamičke utjecaje."],"g-verkehrswege":["Vaš put presijeca markirana pješačka staza. Što je ispravno?","Pješaci mogu pristupiti prijelazu u bilo koje vrijeme.","Uvijek možete zatražiti prednost sirenom.","Smijete voziti preko oznake bez opažanja.","Prilagodite brzinu, pazite na pješake i nastavite vožnju tek kada je staza slobodna.","Prometnim se rutama mora voziti s obzirom na ljude; Znakovi upozorenja ne zamjenjuju sigurnu vidljivost i jasan put."],"g-parkbremse":["Viličar parkirate na ravnom terenu. Što to uključuje?","Želite napustiti vozačevo sjedalo na nekoliko minuta.","Parkirajte, zategnite parkirnu kočnicu i osigurajte od neovlaštene uporabe.","Ostavite vozilo samo u neutralnom položaju.","Ostavite vilicu u visini glave tako da je nitko ne dira.","Prije napuštanja viličar se mora sigurno zaustaviti i osigurati od nenamjernog pomicanja."],"g-typenschild":["Koji podaci su obvezujući kada je u pitanju teret na viličaru?","Želite uzeti težak stroj.","Procijenjena nosivost na temelju veličine vozila.","Podaci proizvođača u dijagramu nosivosti ili nosivosti.","Težina zadnje transportirane palete.","Dopušteno opterećenje određeno je podacima proizvođača i između ostalog ovisi o središtu opterećenja i visini dizanja."],"g-tore":["Viličarom prilazite niskom prolazu. Što provjeravaš?","Na vozilu je visok teret.","Je li prolaz uključujući teret i priključak moguć na siguran način.","Samo visina nosača vilice bez tereta.","Možete li brže proći prije nego što se vrata zatvore.","Prije prolaza potrebno je uzeti u obzir svijetlu visinu i širinu kao i dimenzije tereta i vozila."],"g-reifen":["Tijekom dnevne provjere nalazite jako oštećenu gumu. sta to radis","Na gumi su vidljiva oštećenja važna za sigurnost.","Vozite polako do redovnog termina održavanja.","Povećaš tlak u gumama i nastaviš voziti.","Ne stavljate vozilo u promet i ne prijavljujete štetu.","Oštećene gume mogu utjecati na stabilnost i upravljivost; kvar se mora razjasniti prije uporabe."],"h-absperren":["Zaposlenici prolaze ispod vaše radne platforme. Što je potrebno?","Postoji opasnost od pada alata.","Prikladan zaštitni ili ograničeni prostor ispod radnog mjesta.","Samo obavijest kada prvi put prolazite.","Držite alat što dalje od ruba košare.","Radni prostor ispod povišenih radnih mjesta mora biti osiguran od opasnosti od padajućih dijelova."],"h-werkzeuge":["Kako prenosite alate u radnoj košari?","Na visini je potrebno nekoliko malih alata.","Labavo ih postavite na ogradu tako da budu nadohvat ruke.","Pohranite i osigurajte na takav način da ne padnu ili ometaju rad.","Pričvrstite na vanjsku stranu ograde u džepu.","Labavi predmeti mogu pasti i ugroziti ljude; potrebna je sigurna pohrana."],"h-abstuetzung":["Na poklopcu šahta stoji nosač. Što je potrebno provjeriti?","Želite podići platformu.","Samo provjerite je li poklopac suh.","Može li se teret u tom trenutku sigurno apsorbirati.","Ne trebaju li se drugi nosači koristiti.","Podloga i kontaktna područja moraju biti u stanju sigurno apsorbirati potporne sile; Navlake se moraju procijeniti zasebno."],"h-notaus":["Kada treba koristiti uređaj za zaustavljanje u nuždi?","Odmah dolazi do opasnog pokreta.","Tek na kraju redovne smjene.","Za zaustavljanje u akutnoj opasnosti prema uputama za uporabu.","Kao zamjena za planirano spuštanje.","Zaustavljanje u nuždi koristi se za izbjegavanje opasnosti, a ne uobičajeno upravljanje ili normalno isključivanje."],"h-schraegstellung":["Reagira upozorenje na nagib pozornice. Kako reagirate?","Stroj je na nagnutoj površini.","Ignorirate upozorenje na niskim radnim visinama.","Unatoč upozorenju, vozite u najviši položaj za podizanje.","Zaustavljate se i pozornicu dovodite u sigurno stanje prema uputama proizvođača.","Upozorenja o nagibu mogu ukazivati ​​na neodgovarajuću stabilnost; daljnji pokreti ne smiju povećati opasnost."],"h-umgebung":["Što je potrebno organizirati kod postavljanja u blizini prometne površine?","Vozila mogu dodirivati ​​pozornicu.","Zaštita od sudara i odgovarajuće vođenje prometa.","Zanjihajte radnu košaru što je više moguće preko ceste.","Samo poziv upozorenja prije pokretanja sustava.","Radne platforme s dizalicom moraju biti zaštićene od sudara s korisnicima ceste; instalacija mora biti odgovarajuće osigurana."],"h-ueberlast":["Aktivira se upozorenje o preopterećenju u košari. sta to radis","Pozvani su dodatni alati.","Završite posao većom brzinom.","Odredite dopušteno opterećenje košare i slijedite upute proizvođača.","Trajno isključite signal upozorenja.","Ne smije se prekoračiti maksimalno dopušteno opterećenje košare, uključujući ljude i materijal."],"h-quetschen":["Košaru voziš blizu pod krov. Koja je opasnost posebno važna?","Ostalo je malo prostora iznad koša.","Stezanje ili gnječenje između košare i strukture.","Da motor troši više goriva.","Da se smjer vožnje uvijek automatski mijenja.","Uski prostori iznad ili pored radne košare mogu uzrokovati ozbiljne ozljede od prignječenja."],"h-stromausfall":["Pozornica ostaje na velikoj visini bez glavnog pogona. Što je ispravno?","Normalna kontrola košare više ne reagira.","Spuštate se niz granu bez sigurnosti.","Čekate do kraja svoje smjene, a da niste obaviješteni.","Započnite pripremljeno spašavanje uz pomoć obučenih ljudi i hitno spuštanje.","Sigurno spašavanje mora se planirati za smetnje; Obučeni ljudi moraju poznavati funkcije za hitne slučajeve."],"h-transportstellung":["Kako pripremate pozornicu za prijevoz?","Radna dizalica se utovaruje na odgovarajuće vozilo.","Dovedite granu i platformu u transportni položaj prema uputama za uporabu.","Zavežite platformu što je dalje moguće.","Ostavite podupirače izvučene tako da zauzmu više prostora.","Propisani transportni položaj i osiguranje tereta temelje se na proizvođačkim i transportnim specifikacijama."],"k-bremsprobe":["Što pokazuje funkcionalno ispitivanje kranske kočnice prije uporabe?","Želite biti u mogućnosti sigurno držati teret.","Zaustavlja li se kočnica i zadržava li kretanje kako je predviđeno.","Samo radi li rasvjeta kabine.","Može li kuka automatski držati teret.","Prije uporabe potrebno je provjeriti sigurnosne funkcije u skladu sa specifikacijama."],"k-schraegzug":["Možete li dizalicom vući bočni teret pod kutom?","Kuka nije okomito iznad tereta.","Da, ako dizalica još ima rezervu opterećenja.","Ne, teret se ne smije vući nedopuštenim dijagonalnim potezima.","Da, ako su naramenice posebno kratke.","Dijagonalno povlačenje može uzrokovati nekontrolirane pokrete i dodatno opterećenje dizalice i remena."],"k-verhakt":["Na podkonstrukciju visi teret. Što je ispravno?","Pri dizanju se osjeća otpor.","Nastavljate dizati dok ne ode.","Naglo pomičete teret u stranu.","Zaustavite se i sigurno ćete ukloniti pričvršćivanje ili blokadu.","Zaglavljeni teret ne smije se otpuštati silom jer se mogu pojaviti neprihvatljive sile."],"k-anzuheben":["Što provjeravate kada prvi put nakratko podižete viseći teret?","Teret se podiže nekoliko centimetara od tla.","Visi li u ravnoteži i je li zaustavljanje sigurno.","Može li se osoba izravno staviti pod teret.","Postaje li kran stabilniji brzim okretanjem.","Kratko kontrolirano podizanje koristi se za provjeru pričvršćenja, ravnoteže i sigurnog ponašanja tereta."],"k-lastweg":["Gdje treba biti transportni put tereta dizalice?","Nekoliko radnih mjesta je ispod mogućeg puta opterećenja.","Ako je moguće, iznad zauzetih radnih stanica.","Na planiranoj, jasnoj stazi bez ugroženih ljudi.","Uvijek dijagonalno kroz najprometnije područje.","Putovi tereta moraju biti organizirani tako da ljudi ne budu ugroženi visećim teretom."],"k-signalverlust":["Radio veza s maršalom se prekida. sta to radis","Ne možete vidjeti samu putanju opterećenja.","Polako nastavljate pokret.","Eksperimentalno se okrenete u prethodnom smjeru.","Zaustavljate pokret dok ne dođe do jasnog, sigurnog razumijevanja.","Ako postoji nedostatak komunikacije, zbunjujuće kretanje tereta se možda neće nastaviti."],"k-haken":["Sigurnosna kuka se ne zatvara pouzdano. Što je ispravno?","Tijekom pregleda uočen je neispravan zatvarač.","Pogreška se mora ispraviti stručno prije daljnje uporabe.","Čvrsto zavežete kopču kabelskom vezicom.","Kuku koristite samo za male terete.","Neispravni sigurnosni uređaji na kukama za teret mogu dovesti do toga da se priveznice otkače i moraju se popraviti."],"k-zugrichtung":["Što je važno za okomitu potporu tereta?","Teret treba podići sa stroja.","Kuka dizalice treba biti poravnata iznad težišta tereta.","Udicu treba postaviti što bočnije.","Prije podizanja teret se mora gurnuti.","Učinak sile koji je što je moguće okomitiji iznad središta opterećenja izbjegava nedopuštene bočne sile i nekontrolirano njihanje."],"k-wartung":["Na dizalici se primjećuje neobičan zvuk mljevenja. Kako to činiš?","Buka se javlja prilikom podizanja.","Prikrijte buku većom brzinom.","Zaustavite rad na siguran način, prijavite kvarove i dajte ih razjasniti.","Nastavite s radom bez najave do pauze.","Primjetne promjene mogu ukazivati ​​na oštećenje važno za sigurnost i zahtijevati pregled."],"k-absetzen":["Što mora biti zajamčeno kod spuštanja tereta dizalice?","Teški teret postavljen je na površinu.","Teret može ležati neučvršćen na nagnutoj površini.","Remen se uklanja dok još pluta.","Teret je stabilan i osiguran od prevrtanja ili kotrljanja.","Teret se smije osloboditi s uređaja za vješanje tek nakon što je sigurno postavljen i nakon što je uspostavljena stabilnost."],"l-schwerpunkt":["Zašto se prije udara mora znati težište?","Treba transportirati stroj asimetričnog oblika.","Tako da teret prilikom podizanja ostane što je moguće više uravnotežen.","Tako da se remenčići mogu birati dugi po želji.","Tako da dopuštena nosivost ne igra nikakvu ulogu.","Položaj težišta utječe na raspodjelu tereta i sigurnu ravnotežu pri dizanju."],"l-etikett":["Traka za podizanje nema čitljivu oznaku nosivosti. Što je ispravno?","Markacija je postala neprepoznatljiva.","Procijenite nosivost na temelju boje.","Ne koristite traku za podizanje dok se jasno ne dokaže njezina prikladnost.","Koristite pojas samo jednom za mala opterećenja.","Za priveznice su potrebne odgovarajuće oznake; Neobjašnjen kapacitet nosivosti onemogućuje siguran odabir."],"l-kantenschutz":["Tekstilna traka leži preko oštrog čeličnog ruba. Što je potrebno?","Teret ima oštre rubove.","Povucite traku što je moguće čvršće bez zaštite.","Izvedite udarac brže.","Koristite prikladnu zaštitu rubova ili drugu prikladnu opremu za vrpcu.","Oštri rubovi mogu oštetiti ili rezati tekstilne remenčiće; potrebna je odgovarajuća zaštita."],"l-spreizwinkel":["Kako veći kut nagiba utječe na opterećenje priveznica?","Teret se podiže pomoću dva kosa užeta.","Pod manje povoljnim kutovima, sile u nitima mogu porasti.","Strand sile nestaju.","Kut nema utjecaja na naprezanje.","S manje povoljnim zaustavnim kutom, sile po niti mogu se povećati; Potrebno je poštivati ​​tablice nosivosti."],"l-knoten":["Može li se uže za remen po želji skratiti pomoću čvora?","Uže je predugačko za planirano opterećenje.","Da, čvrsti čvor povećava nosivost.","Ne, koristite samo odobrene metode skraćivanja i sidrenja.","Da, ako je čvor pričvršćen trakom.","Nedopušteni čvorovi slabe priveznice i mijenjaju njihovu dopuštenu nosivost."],"l-zeichen":["Što se odnosi na komunikaciju s osobom koja upravlja dizalicom?","Put tereta je djelomično zaklonjen.","Nekoliko ljudi daje različite signale u isto vrijeme.","Koriste se jasni, prethodno dogovoreni signali.","Komunikacija nikada nije potrebna s radio dizalicama.","Jasni znakovi i jasne odgovornosti sprječavaju opasne nepravilne pokrete."],"l-sichtpruefung":["Kada remen treba provjeriti na vidljive nedostatke?","Želite koristiti lanac za remen.","Prije uporabe obratite pozornost na eventualna izvana vidljiva oštećenja.","Samo ako se nesreća već dogodila.","Samo jednom prilikom prve kupnje.","Prije svake uporabe moraju se procijeniti sigurni radni uvjeti; Vidljiva oštećenja onemogućuju sigurnu uporabu."],"l-drehung":["Podignuti teret počinje se nekontrolirano okretati. sta to radis","Teret se kreće po putu opterećenja.","Stavite ruku između tereta i zida.","Stavljate se pod teret i držite ga se.","Držite distancu i kontrolirano pustite kretanje.","Nekontrolirano pomicanje tereta stvara opasnost od prignječenja i udara; Ljudi moraju napustiti opasno područje."],"l-ablegen":["Kada se priveznice mogu skinuti s tereta?","Teret se postavlja na nosače.","Ako je teret stabilan i osiguran od prevrtanja ili kotrljanja.","Čim prvi put dotakne tlo, bez obzira na položaj.","Dok još lebdi da uštedi vrijeme.","Priveznice se smiju skinuti tek nakon što su sigurno i stabilno postavljene."],"l-ketten":["Lančana remen ima jako savijenu kariku. sta to radis","Oštećenja su vidljiva i prije podizanja.","Omotajte oštećeno mjesto žicom.","Izvadite lanac iz uporabe i dajte ga na stručnu provjeru.","Podignite teret samo upola manje.","Deformirane karike lanca vidljiva su oštećenja koja mogu spriječiti sigurnu uporabu."],"b-einweiser":["Što je važno kada je vidljivost iz bagera ograničena?","Dio zgrade zaklanja prostor za vožnju.","Odgovarajuće vizualne mjere ili upute i jasna komunikacija.","Samo pazi na haubu.","Vozite kroz zakretno područje iako ste nevidljivi.","Ako je vidljivost ograničena, opasnosti se moraju spriječiti dodatnim organizacijskim i tehničkim mjerama."],"b-aushub":["Gdje se može skladištiti iskopani materijal u blizini građevinske jame?","Rub jame ne smije biti dodatno ugrožen.","Nagomilajte izravno na rub tako da prilazi ostanu slobodni.","Skladištiti na dovoljno sigurnoj udaljenosti i prema specifikacijama gradilišta.","Stavite na labavu podlogu bez daljnjeg testiranja.","Iskopani materijal može ugroziti nasipe i podupirače zbog dodatnih opterećenja; Moraju se održavati sigurnosne udaljenosti."],"b-personen":["Smiju li ljudi ostati u području zakretanja dok se bager kreće?","Osoba želi mjeriti tijekom pomicanja.","Da, sve dok nosi zaštitnu kacigu.","Da, ako se bager polako ljulja.","Ne, opasno područje mora biti slobodno prije kretanja.","Postoji opasnost od ozbiljnog prignječenja i ozljeda od udarca u području zakretanja; područje mora biti čisto."],"b-ladung":["Kako sigurno prevozite materijal s utovarivačem na kotačima?","Napunjenu lopatu treba voziti po dvorištu.","S prikladnim niskim transportnim položajem i čistim putem.","S podignutom lopatom za bolju vidljivost.","S otvorenim vratima i jakim kutom upravljanja.","Prikladan transportni položaj smanjuje rizik od prevrtanja i poboljšava stabilnost u vožnji."],"b-anbaupruefung":["Što provjeravate nakon spajanja priključka?","Priložena je nova lopata.","Samo čistoća laka.","Sigurno zaključavanje i rad prema uputama za uporabu.","Samo da li uređaj izvana izgleda isto.","Neispravne brave na brzim spojnicama mogu dovesti do nenamjernog otpuštanja priključaka."],"b-einstieg":["Kako sigurno ući u kabinu bagera?","Stepenice su prljave nakon kiše.","Popnite se u kabinu preko poluge.","Popnite se na gusjenice u jednom skoku.","Koristite predviđene stepenice i rukohvate i očistite prljave stepenice.","Prikladni usponi i sigurne točke za držanje smanjuju rizik od klizanja i pada."],"b-graben":["Zid rova ​​pokazuje pukotine i raspada se. Što je ispravno?","Radite tik uz jarak.","Prekinite radove i neka odgovorni osiguraju iskopnu jamu.","Jednostavno vozite bliže rubu kako biste zatvorili jarak.","Dodatno produbiti rov bez zaštite.","Pukotine i pomicanja tla mogu ukazivati ​​na nestabilnost i zahtijevaju dodatnu procjenu sigurnosti."],"b-betanken":["Na što obraćate pozornost prilikom punjenja goriva u stroj za zemljane radove?","Spremnik je skoro prazan.","Osigurajte motor i izvore paljenja u skladu s uputama proizvođača i izbjegavajte prolijevanje.","Benzin ili dizel uvijek dolijevajte u kabini.","Dimite tijekom točenja goriva kada nema vjetra.","Opasnosti od požara i okoliša pri rukovanju gorivom zahtijevaju odgovarajuće zaštitne mjere."],"b-laufwerk":["Zašto gusjenice i podvozje treba redovito provjeravati?","Primijetili ste neobične vibracije tijekom vožnje.","Tako da se stroj može brže kretati.","Jer oštećenje može utjecati na sigurno vođenje i stabilnost.","Jer rad je uvijek dopušten bez vizualnog pregleda.","Oštećenje pogona može utjecati na sposobnost manevriranja, stabilnost i siguran rad."],"b-einweisen":["Što je potrebno pri radu u blizini javnog pješačkog prometa?","Bager radi izravno na rubu nogostupa.","Pješaci se trebaju sami kretati ljuljačkom.","Samo zalijepite znak na lopatu.","Učinkovito ogradite opasno područje i sigurno usmjerite promet.","Treće osobe ne smiju ulaziti u opasnu zonu strojeva za zemljane radove; Potrebne su odgovarajuće barijere i usmjeravanje prometa."],"g2-fahrweg":["Na cesti ispred je prolivena tekućina. Kako to činiš?","Viljuškar bi vozio izravno preko skliskog područja.","Prekinite vožnju i osigurajte ili uklonite opasno mjesto.","Vozite mjesto što je brže moguće s podignutom vilicom.","Nadajte se sušim gumama i nastavite voziti bez promjena.","Onečišćeni putovi ugrožavaju stabilnost i prije vožnje po njima moraju biti odgovarajuće osigurani."],"g2-sichtladung":["Visoka paleta zaklanja pogled naprijed. Što je ispravno?","Morate se odvesti do skladišnog prostora i ne možete vidjeti rutu.","Podignite paletu dok ne vidite ispod nje.","Vozite samo odgovarajućim, sigurnim metodama, kao što je vožnja unatrag s jasnim pogledom.","Još uvijek možete voziti cestom bez putokaza ili jasnog pogleda.","Smjer vožnje i preglednost moraju omogućiti sigurno promatranje prometnog pravca; Opterećenja ne smiju zamijeniti vizualni pregled."],"g2-fussgaengerstop":["Odmah do viličara staje pješak. sta to radis","Osoba je unutar mogućeg dometa vožnje i okretanja.","Prestignite pješaka kratkim ubrzanjem.","Prođite pokraj osobe s podignutim teretom.","Zaustavite se i nastavite vožnju samo na sigurnoj udaljenosti.","Ljudi se moraju držati podalje od opasnog područja; U slučaju potrebe, putovanje se mora prekinuti."],"g2-hubmast":["Primijetili ste oštećeni hidraulički vod na stupu dizala. Što se primjenjuje?","Hidraulično ulje vidljivo curi iz priključka.","Isključiti viličar iz pogona i prijaviti štetu.","Tijekom podizanja rukom provjerite curenje.","Manje terete podižite samo do kraja smjene.","Hidrauličko oštećenje može dovesti do nekontroliranih pokreta; sigurna uporaba nije zajamčena do testa."],"g2-lagerregal":["Želite spremiti paletu na policu. Što prvo provjerite?","Razina polica je visoka i nosivost se mora održati.","Gurnite paletu na policu što je brže moguće.","Provjerite prikladnost pretinca za police, težinu tereta i slobodnog prostora za pohranu.","Procijenite ukupnu težinu isključivo na temelju broja kutija.","Police i oprema za nošenje tereta moraju odgovarati teretu i situaciji skladištenja."],"g2-batterieschaden":["Baterija viljuškara je oštećena izvana. Što je ispravno?","Prije utovara uočavaju se pukotine ili neobična tekućina.","Pokrijte oštećenja ljepljivom trakom i odmah opteretite.","Neka druga osoba puni bateriju bez provjere.","Nemojte puniti niti koristiti i obavijestite odgovorne stručnjake.","Oštećene baterije predstavljaju električnu i kemijsku opasnost i zahtijevaju stručnu procjenu."],"g2-fahrerkabine":["Što se odnosi na labave predmete u području vozača?","Alati su na podu pored kontrolnih pedala.","Uklonite predmete i držite radno područje čistim.","Tijekom vožnje alat držite samo jednom nogom.","Sakrijte labave dijelove ispod vozačevog sjedala.","Labavi predmeti mogu blokirati pedale i ugroziti siguran rad vozila."],"g2-uebergabe":["Vi preuzimate viličar nakon promjene smjene. Što to uključuje?","Kolega je zadnji koristio vozilo.","Pretpostavimo da je kolega preuzeo sve provjere.","Provedite potrebne preglede i raspitajte se o poznatim nedostacima.","Započnite putovanje bez gledanja u stroj.","Osoba koja preuzima mora osigurati da je u sigurnom stanju prije uporabe."],"g2-transportsicherung":["Visoki predmet je labav na paleti. kako se ponašaš","Teret bi se mogao prevrnuti prema naprijed prilikom kočenja.","Nosite vilicu posebno visoko kako bi teret ostao stabilan.","Samo polako u zavoje, ravno brže.","Postavite teret na stabilan način i osigurajte ga od prevrtanja ili pada.","Labavi tereti moraju se stabilizirati prije prijevoza kako kočenje i vožnja ne bi uzrokovali pad."],"g2-arbeitsende":["Što je važno kod viličara bez nadzora?","Završavate smjenu i napuštate područje.","Vozilo parkirajte na sigurno i osigurajte ga od kotrljanja i neovlaštene uporabe.","Ostavite ključ unutra da kolege mogu pronaći stroj.","Ostavite vilicu u razini očiju tako da bude vidljiva.","Sigurno parkiranje uključuje rukovanje spuštenim teretom i zaštitu od pomicanja i neovlaštenog puštanja u pogon."],"g2-bremsweg":["Zašto morate posebno paziti na put kočenja pod opterećenjem?","Viljuškar prevozi tešku robu kroz skladišni prostor.","Uvijek kočite kasnije s velikim teretom nego bez tereta.","Prilagodite brzinu vidljivosti, tlu i uvjetima opterećenja.","Prilikom kočenja naglo podignite teret kako biste bolje usporili.","Masa i stanje ceste utječu na zaustavni put; prilagođena brzina je ključna."],"g2-rampe":["Što provjeravate prije penjanja uz strmu rampu?","Ruta je možda prestrma za vozilo.","Vozite po rampi maksimalnom brzinom bez obzira na uspon.","Vozite preko ruba rampe s podignutim teretom.","Provjerite dopušteni nagib i siguran način rada prema specifikacijama vozila.","Mogu se koristiti samo rampe unutar predviđenih radnih granica; Upute za rad i kontrola opterećenja su odlučujući."],"g2-zinke":["Paleta je šira od udaljenosti vilice. Što treba uzeti u obzir?","Planirate preuzeti neobično velik teret.","Prilagodite udaljenost vilice i točke pričvršćivanja prema teretu.","Koristite samo jedan zubac ako je teret preširok.","Podignite teret pod kutom dok ne dođe u pravilan položaj.","Ravnomjerno i prikladno upijanje opterećenja smanjuje klizanje i prevrtanje."],"g2-betriebsanweisung":["Kakvu ulogu ima operativna regulacija prometa?","U skladištu vrijede označene jednosmjerne i pješačke površine.","Kod viličara vrijede samo pravila javnog prometa.","Pridržavajte se navedenih ruta i prometnih pravila.","Zanemarite oznake nakon što je vozilo utovareno.","Putevi poduzeća i sigurnosna pravila štite promet viličarima i pješake."],"g2-nothalt":["Upravljač neobično reagira tijekom vožnje. Što je ispravno?","Vozilo se više ne može kontrolirati kao inače.","Vozite većim brzinama kako bi upravljač bolje reagirao.","Kompenzirajte pogrešku kod posebno velikih otklona upravljača.","Zaustavite se na sigurnom mjestu i dajte vozilo na pregled.","Loše upravljanje ugrožava sigurno vođenje; stroj ne smije nastaviti raditi nekontrolirano."],"g2-anschlagkette":["Viličarom želite pomaknuti teret koji slobodno visi. Što se primjenjuje?","Teret bi trebao visjeti na kuki ispod vilica.","Samo s odobrenim uređajem i odgovarajućom opremom za nošenje tereta.","Svaki lanac je dovoljan ako teret nije težak.","Pričvrstite lanac izravno između obje vilice.","Slobodno viseći tereti mijenjaju stabilnost; Potrebna su odobrenja proizvođača i odgovarajući objekti."],"g2-rollenlast":["Cilindrična komponenta leži neosigurana na paleti. sta to radis","Teret se može otkotrljati tijekom transporta.","Posebno trzavo prilazite paleti.","Prije preuzimanja palete osigurajte komponentu od kotrljanja.","Postavite zupce dovoljno visoko da se komponenta ne vidi.","Okrugli ili kotrljajući tereti zahtijevaju pouzdanu zaštitu od promjena položaja."],"g2-pruefplakette":["Kako znate može li se viličar koristiti?","Na stroju je zalijepljena inspekcijska naljepnica.","Svaka naljepnica uvijek zamjenjuje dnevni vizualni pregled.","Nedostatak zazora može se zamijeniti opreznom vožnjom.","Osim provjere vozila, potrebno je uzeti u obzir važeći testni status i operativno odobrenje.","Ponavljajuća testiranja i svakodnevne operativne kontrole ispunjavaju različite sigurnosne funkcije."],"g2-licht":["Rasvjeta u skladištu se odjednom ugasila. Što je ispravno?","Više ne možete sigurno vidjeti prepreke na putu.","Zaustavite vožnju dok se ne osigura sigurna vidljivost.","Povećajte brzinu vožnje kako biste napustili tamno područje.","Nastavite vožnju s podignutim vilicama bez vizualnog pregleda.","Put koji se ne može sigurno previdjeti ne smije se voziti bez učinkovitih sigurnosnih mjera."],"g2-ueberhang":["Teret se proteže daleko izvan bočne strane vilice. Što provjeravaš?","Želite transportirati paletu kroz uska vrata.","Nadoknadite bočnu projekciju brzom krivuljom.","Prije vožnje procijenite razmak, stabilnost i dopuštenu nosivost.","Vozite teret maksimalnom brzinom bez obzira na njegov oblik.","Prevjesi povećavaju rizik od sudara i mogu promijeniti stabilnost i potreban prometni prostor."],"g2-wartungsbereich":["Postoje barijere ispred područja održavanja. kako se ponašaš","Vaša uobičajena ruta je privremeno zatvorena.","Nakratko pomaknite barijere i prođite neprimjetno.","Vozite izravno kroz radno područje pod opterećenjem.","Poštujte zatvaranje i odaberite odobrenu alternativnu rutu.","Ograđena područja ne smiju se ulaziti niti se kroz njih voziti bez dopuštenja."],"g2-bremsprobe":["Kada ima smisla funkcionalna provjera radne kočnice?","Viličar pripremate prije rada.","Kao dio potrebnog pregleda prije uporabe.","Izvršite samo nakon teške nesreće.","Samo ako je kamion već postigao veliku brzinu.","Funkcionalnost sigurnosno bitnih objekata provjerava se prije uporabe."],"g2-fahrzeuganhaenger":["Želite vući prikolicu viličarom. Što je potrebno?","Tvrtka planira prijevoz s prikačenim teretom.","Privežite svaku prikolicu na vilicu bez provjere.","Pridržavajte se odobrenja proizvođača, prikladne spojke i dopuštenog vlačnog opterećenja.","Samo povećajte tlak u gumama i krenite.","Vožnja vlakom moguća je sigurno samo unutar tehničkih specifikacija i uz odgovarajuću vezu."],"g2-rueckfahrt":["Što je važno pri vožnji unatrag s viličarom?","Postoji zbunjujuće područje u prolazu skladišta.","Uvijek gledajte samo u retrovizor, bez obzira na okolinu.","Vozite bez vidljivosti sve dok je sirena jednom pritisnuta.","Sigurno promatrajte rutu i područje ljudi i, ako je potrebno, dajte im upute.","Vožnja unatrag zahtijeva jasan pogled ili učinkovite dodatne sigurnosne mjere."],"g2-lastentnahme":["Uzimate paletu s visoke police. Što je ispravno?","Paleta možda nije centrirana.","Podignite teret na siguran način i stabilizirajte ga prije spuštanja.","Pustite paletu da se okrene u stranu dok je izvlačite.","Provjerite ispod podignute palete je li oštećena.","Kontrolirano podizanje i spuštanje sprječava pad tereta i opasna pomicanja."],"h2-absenkweg":["Zašto područje ispod radne platforme mora ostati slobodno?","Košara se spušta i ispod nje se stavlja materijal.","Pritisnite materijale košarom prema dolje.","Pazite samo na područje stopala operatera.","Izbjegnite rizik od prignječenja i sudara prilikom spuštanja.","U području spuštanja ne smiju biti ljudi ili prepreke koje bi se mogle zaglaviti."],"h2-transporthoehe":["Kako premjestiti pokretnu pozornicu preko niskog prolaza?","Razmak je niži od produljene grane.","Postavite platformu u odgovarajući transportni položaj prema uputama za uporabu.","Ostavite polugu ispruženu i krenite ispod stropa.","Pritisnite košaru uz rub okvira vrata.","Za kretanje, ukupna visina i transportni položaj moraju odgovarati specifikacijama proizvođača i prolazu."],"h2-bodenoeffnung":["U podu pokraj pozornice nalazi se neosigurani otvor. Kako reagirate?","Vozna ili potporna točka nalazi se u blizini otvora.","Postavite nosač izravno na rub otvora.","Promijenite mjesto postavljanja ili neka stručna provjera nosivosti i učvršćenja.","Prekrijte samo mjesto opasnosti kartonskom kutijom.","Otvori i rubna područja mogu otkazati pod opterećenjem potpore i to se mora učinkovito uzeti u obzir."],"h2-rettungsperson":["Zašto druga osoba mora biti upoznata s postupkom spašavanja?","Operater bi mogao postati nesposoban na vrhu.","Tako da se rad u košari uglavnom može odvijati bez osiguranja.","Tako da se pozornicom može upravljati brže nego što je dopušteno.","Kako bi se u hitnim slučajevima moglo pokrenuti sigurno spašavanje.","Koncept spašavanja mora uzeti u obzir pomoć sa zemlje u slučaju kvara ili hitnog slučaja."],"h2-werkzeugabwurf":["Što se odnosi na alate na velikoj nadmorskoj visini?","Labavi alat mogao bi pasti preko ruba košare.","Osigurajte alat tako da nikoga ne ugrozi ili padne.","Jednostavno postavite alat na ogradu kako biste smanjili opterećenje.","Ako je potrebno, bacite alat iz košare.","Predmeti koji padaju ugrožavaju ljude ispod; Materijal mora biti sigurno pohranjen."],"h2-trittstufe":["Kutija bi trebala poslužiti kao dodatni prostor za stajanje u košari. Što je ispravno?","Inače ćete jedva doći do radnog mjesta.","Stavite kutiju na ogradu i popnite se na nju.","Nemojte se penjati na improvizirane uzvisine; Koristite odgovarajuću radnu opremu.","Namjerno napunite košaru iznad dopuštene visine.","Improvizirana uzvišenja umanjuju predviđenu zaštitu od pada i nisu dopuštena."],"h2-lastverteilen":["Na što obraćate pozornost kada je u radnoj košari više ljudi?","Dvoje ljudi radi u košari s teškim alatom.","Procijenite opterećenje isključivo na temelju veličine alata.","Spremite teške alate izravno na zaštitnu ogradu.","Nemojte prekoračiti dopušteno opterećenje košare, uključujući ljude i alate.","Dopuštena nosivost uključuje sve ljude, materijale i alate u košari."],"h2-abstuetzplatte":["Kada se razmatraju dodatne podloške za nosače?","Instalacijski pod može podnijeti samo ograničeno opterećenje.","Ako je to potrebno za sigurnu raspodjelu opterećenja prema specifikacijama.","Kako bi se nosači postavili što bliže rubu građevinske jame.","Za korištenje većeg dometa bez podataka o proizvođaču.","Za sigurne snage podrške potrebno je dovoljno kontaktnih površina."],"h2-baugrube":["Pozornicu treba postaviti neposredno uz rub građevinske jame. Što provjeravaš?","Podtlo bi moglo popustiti bočno zbog jame.","Produžite nosače u jamu za iskop.","Osigurati dovoljan sigurnosni razmak i nosivost podloge.","Rizik nadoknadite samo polaganim podizanjem košare.","Jame za iskop mogu utjecati na stabilnost zbog nagiba i loma podzemlja."],"h2-witterung":["Zaleđivanje se stvara tijekom upotrebe. kako se ponašaš","Kontrolne površine i radni prostor postaju glatki.","Podignite pozornicu kako biste izbjegli snijeg i led.","Ignorirajte upozorenja sve dok je platforma osvijetljena.","Prekinite rad i ponovno procijenite radne uvjete prema uputama za uporabu.","Promjene vremena mogu promijeniti odgovornost, operativnost i sigurne granice uporabe."],"h2-aufbaukontakt":["Čelična konstrukcija ograničava put košare. Što je važno?","Prilikom podizanja postoji opasnost od prignječenja između košare i nosača.","Planirajte pokrete tako da vam tijelo i košara ne budu zarobljeni.","Ubrzajte putovanje kako bi košara brže prošla.","Gurnite konstrukciju s košarom u stranu.","Točke priklještenja između platforme i okoline zahtijevaju pažljivo promatranje i kontrolirano kretanje."],"h2-sicherheitsabstand":["Kada opasno područje pozornice mora biti ograđeno?","Ispod terena prolazi trasa javnog prijevoza.","Samo ako je neki predmet već pao.","Ako bi treće osobe mogle biti ugrožene kretanjem ili padom predmeta.","Nikad, jer radna košara zapravo sprječava sve opasnosti.","Područje ispod i uz pozornicu mora biti zaštićeno od predvidivih opasnosti."],"h2-korbtor":["Što se odnosi na ulazna vrata radne košare?","Već ste na radnoj visini.","Ostavite vrata otvorena kako biste brže izašli.","Zavežite vrata trajno otvorenim užetom.","Držite vrata zatvorena u skladu s isporučenim mehanizmom za zaključavanje.","Priložene brave dio su zaštitnih mjera protiv pada s radne košare."],"h2-energieleitung":["Što se primjenjuje ako nadzemni vod nije sigurno isključen?","Radite s dizalicom u njihovoj blizini.","Osigurajte navedene sigurnosne udaljenosti i potrebne zaštitne mjere.","Pomaknite košaricu točno ispred linije sve dok je ne dodirnete.","Povjerite se plastičnim gumama i radite bez zazora.","Električni bljeskovi su također mogući bez izravnog kontakta; Potrebni su sigurnosni razmaci."],"h2-schwanken":["Radna košara počinje se neobično snažno njihati. Što je ispravno?","Kretanje više nije kontrolirano.","Nekontrolirano ponovno namjestite brzim protupokretima.","Zaustavite kretanje i provjerite uzrok ili radne uvjete.","Dodajte dodatne osobe u košaru kako bi bila teža.","Neuobičajene vibracije mogu ukazivati ​​na neprikladne uvjete rada ili kvar."],"h2-ladegeraet":["Oštećen je kabel za punjenje električno upravljane pozornice. sta to radis","Prilikom spajanja vidljiva je oštećena izolacija.","Dodirnite oštećenje mokrim rukavicama.","Pritisnite utikač u utičnicu što je jače moguće.","Ne započinjite proces punjenja i dajte kabel na stručnu provjeru.","Oštećeno električno ožičenje predstavlja opasnost od strujnog udara i požara."],"h2-gelaenderanbau":["Možete li sami ukloniti ogradu da biste se približili?","Komponenta sprječava ljude da priđu gradilištu.","Nemojte sami mijenjati ili uklanjati zaštitne uređaje.","Nakon podizanja, odvrnite ogradu i postavite je kasnije.","Nastavite raditi bez ograde sve dok netko stoji uz nju.","Strukturni zaštitni uređaji ne smiju se mijenjati bez dopuštenih specifikacija i mjera sigurne zamjene."],"h2-lastkran":["Može li se platforma koristiti kao dizalica za podizanje tereta?","Materijal treba transportirati slobodno viseći uz radnu košaru.","Kad god je težina manja od težine vlastitog tijela.","Samo ako proizvođač i oprema izričito dopuštaju ovu posebnu uporabu.","Jednostavno pričvrstite kuku na ogradu i podignite materijal.","Radne platforme na visini nisu automatski dizajnirane za rad dizalicom ili dodatni viseći teret."],"h2-arbeitsvorbereitung":["Što ulazi u pripremu za novu lokaciju?","Još ne poznaješ gradilište.","Samo procijenite udaljenost do najbližeg parkirališta.","Bez obzira na okolinu, odmah ga potpuno proširite.","Procijeniti opasnosti, tlo, prometne putove, spašavanje i prikladnost opreme.","Procjena rizika vezana uz lokaciju preduvjet je za sigurne radne uvjete."],"h2-kabelschlaufe":["Kabel za napajanje nalazi se preko puta pozornice. Što je ispravno?","Kabel bi se mogao zaglaviti tijekom pomicanja.","Očistite cestu i zaštitite električne kablove od oštećenja.","Koristite sajlu s kotačima kao prag ceste.","Podignite košaru bez provjere površine poda.","Pregaženi ili zgnječeni kabeli mogu uzrokovati električne i mehaničke opasnosti."],"h2-leitungsnaehe":["Tko pojašnjava zaštitne mjere na električnom sustavu?","Platforma bi trebala raditi u blizini žive opreme.","Osoba u košarici odlučuje isključivo na oko.","Uključiti nadležna tijela i provoditi koordinirane mjere zaštite.","Udaljenost će se odrediti tek nakon početka radova.","Rad u blizini električnih sustava zahtijeva planirane i koordinirane zaštitne mjere."],"h2-funkkommunikation":["Zašto signali između poda i koša moraju biti jasni?","Osoba na tlu pomaže pri manevriranju.","Tako da više ljudi može davati kontradiktorne upute u isto vrijeme.","Tako da se hitno spuštanje može isprobati bez instrukcija.","Tako da se pokreti izvode samo nakon jasne komunikacije.","Jasna komunikacija smanjuje pogrešna kretanja i sudare pri manevriranju."],"h2-neuebedienung":["Prebacujete se na drugu vrstu pozornice. Što je potrebno?","Funkcije rada značajno se razlikuju.","Upute specifične za uređaj prije samostalne uporabe.","Samo čitanje logotipa tvrtke na uređaju.","Probna vožnja s već produženom košaricom bez uputa.","Sama kvalifikacija ne zamjenjuje poduku u određenoj vrsti uređaja."],"h2-steckanschluss":["Što trebate provjeriti prije spajanja punjača?","Potrebno je napuniti električnu dizalicu.","Koristite bilo koju utičnicu bez obzira na stanje i osigurač.","Provjerite odgovarajući priključak i neoštećeni kabel prema uputama proizvođača.","Tijekom punjenja redovito izvucite utikač iz utičnice.","Prikladni i neoštećeni električni priključci štite od strujnog udara i požara."],"h2-absperrpersonal":["Osoba ulazi u ograđeno područje tijekom radova na dizanju. sta to radis","Možete vidjeti osobu izravno ispod radne košare.","Nastavite vožnju ako osoba nosi zaštitnu kacigu.","Ispustite alat u njihovom smjeru kao znak upozorenja.","Zaustavite opasno kretanje i raščistite područje.","Barijera ne zamjenjuje promatranje opasnog područja tijekom rada."],"k2-arbeitsplanung":["Što treba uključiti u pripremu rada prije rada dizalice?","Utovar, mjesto i ruta prijevoza još nisu usklađeni.","Prvo podignite najteži teret bez daljnjeg planiranja.","Označite samo najkraći put na podu dvorane.","Unaprijed razjasnite nosivost, priveznice, putanju tereta i opasno područje.","Planirano kretanje dizalice zahtijeva odgovarajuće rukovanje teretom, sigurne rute i koordinirane zaštitne mjere."],"k2-hakenposition":["Kako se kuka dizalice postavlja iznad tereta prije podizanja?","Točke pričvršćivanja su ispod dizalice.","Što okomitije iznad težišta prema zaustavljanju.","Pomaknuti daleko u stranu kako bi se teret brže zaljuljao.","U svakom slučaju na vanjskom rubu tereta, bez obzira na težište.","Vertikalna primjena sile i prikladne sidrišne točke smanjuju bočno kretanje i nekontrolirana kretanja."],"k2-hakengabel":["Kuka za teret pokazuje primjetnu deformaciju. Što se primjenjuje?","Udica izgleda savijena u odnosu na uobičajeno stanje.","Savijte deformaciju natrag sa sljedećim opterećenjem.","Zaustavite rad dizalice i neka kuku provjeri stručnjak.","Pričvrstite samo lagane terete i nastavite s radom.","Deformacija može utjecati na sigurnost udice; daljnja neovlaštena uporaba nije dopuštena."],"k2-zugueberlast":["Teret je veći nego što se isprva pretpostavljalo. sta to radis","Nove informacije o težini pojavljuju se tijekom pripreme.","Zamijenite sigurnosnu rezervu bržim podizanjem.","Zanemarite težinu tereta tako da ga pričvrstite na drugu točku.","Odredite stvarno opterećenje i ponovno provjerite ograničenja opterećenja.","Za sigurno podizanje potrebni su pouzdani podaci o opterećenju i usklađenost sa svim relevantnim nosivostima."],"k2-arbeitskorb":["Može li obična kuka dizalice lako prevoziti ljude?","Osoba želi doći na visoko radno mjesto.","Ne, prijevoz putnika zahtijeva dopuštene posebne pogodnosti i mjere.","Da, ako se osoba drži za uže za remen.","Da, čim se udarac izvodi posebno sporo.","Prijevoz ljudi dopušten je samo pod posebnim uvjetima predviđenim za tu svrhu."],"k2-bruecke":["Mosna dizalica kreće se zajedničkom stazom hale. Što je važno?","Zaposlenici ostaju ispod transportne rute.","Vozite s teretom točno iznad glava zaposlenika.","Učinkovito održavajte put tereta i prometnu površinu čistim i sigurnim.","Koristite samo sirenu upozorenja umjesto daljnjih mjera.","Ugrožene osobe ne smiju biti ispod visećeg tereta ili na njihovom transportnom putu."],"k2-zweitekrane":["Dvije dizalice rade u području koje se preklapa. Što je potrebno?","Grane ili tereti mogu se sudariti jedni s drugima.","Oba kranista rade istovremeno bez prethodnog dogovora.","Kretanja su namjerno ubrzana kako bi se izbjegla raskrižja.","Koordinirati operacije i poduzeti odgovarajuće mjere za sprječavanje međusobnih prijetnji.","Radna područja koja se preklapaju zahtijevaju koordiniranu operativnu organizaciju i odgovarajuće zaštitne mjere."],"k2-pruefbuch":["Koji je značaj obaveznog redovnog pregleda dizalice?","Stroj se redovito koristi u radu.","Pogonsku kontrolu dopunjuje propisanim stručnim pregledom.","Trajno zamjenjuje svaki vizualni pregled prije početka rada.","Potrebno je samo nakon sudara.","Ponavljajuće inspekcije i stalne operativne kontrole imaju različite zadatke."],"k2-absetzflaeche":["Predviđeno područje postavljanja je neravnomjerno. kako se ponašaš","Teret bi se mogao prevrnuti kada se postavi.","Stavite teret na jedan kut i ostavite da visi nepromijenjen.","Pripremite odgovarajuće, nosive i stabilne podloge ili površine.","Stavite jednu osobu ispod tereta tijekom spuštanja.","Područja za postavljanje moraju sigurno nositi teret i spriječiti opasno prevrtanje ili kotrljanje."],"k2-anfahrbereich":["Prije nego što se dizalica pokrene, jedna je osoba u zoni kretanja. sta to radis","Put je blokiran od strane osobe.","Odgurnite osobu u stranu kratkom probnom vožnjom.","Krenite samo pomoću graničnog prekidača bez vizualnog pregleda.","Počnite s kretanjem tek kada je opasno područje slobodno i sigurno.","Vožnja i zakretanje ne smiju ugrožavati ljude."],"k2-schlaffseil":["Zašto uže za podizanje ne bi trebalo nekontrolirano olabaviti kada se spusti?","Teret je uključen, kuka se dalje spušta.","Kako se uže i kuke ne bi zaglavili ili podvrgli nekontroliranom opterećenju.","Tako da se teret zatim može bočno povući užetom.","Tako da se privezi sami odvajaju od udice.","Nekontrolirano provođenje kabela može dovesti do zapetljanja i opasnih pomicanja tereta."],"k2-pendel":["Teret koji se prevozi počinje se ljuljati. Što je ispravno?","Teret se bočno pomiče više od planiranog.","Kompenzirajte brzim protupokretima i punom brzinom.","Kontrolirano smanjite kretanje i umirite putovanje na posao bez ljudi u opasnom području.","Držite teret koji se ljulja golim rukama.","Oscilirajuća opterećenja mogu utjecati na ljude i objekte; smireni pokreti smanjuju rizik."],"k2-funkakku":["Radio kontrola dizalice ima slabu bateriju. Što se primjenjuje?","Veza bi mogla puknuti tijekom podizanja.","Brzo podignite teret prije nego što kontrola otkaže.","Ako se veza izgubi, pomaknite teret povlačenjem remena.","Prije uporabe osigurajte pouzdanu kontrolnu vezu.","Pouzdana kontrola i komunikacija su preduvjeti za kontrolirano kretanje dizalice."],"k2-mehrereanschlaeger":["Dvije osobe istovremeno daju različite signale rukovatelju dizalice. Što je ispravno?","Znakovi su u suprotnosti jedan s drugim.","Prekinite kretanje i razjasnite jasnu odgovornost.","Dajte prednost znaku osobe koja je dalje.","Nastavite pokret prema vlastitom osjećaju.","Vozači dizalica trebaju jasnu i nedvosmislenu komunikaciju, posebno kada su rute tereta zbunjujuće."],"k2-endabschaltung":["Zašto se granični prekidač ne smije zloupotrijebiti kao normalno ograničenje hoda?","Teret se često pomiče do najveće udaljenosti podizanja.","Granični prekidači općenito omogućuju brže podizanje bez vidljivosti.","Granični prekidači su sigurnosni uređaji i ne zamjenjuju kontrolirani rad.","Treba ih udarati što je jače moguće pri svakom udarcu.","Sigurnosni uređaji služe za zaštitu od opasnosti i ne smiju se pretjerano koristiti prema planu."],"k2-wetterbeobachtung":["Vjetar se značajno povećava s velikim opterećenjem površine. Što je potrebno?","Velika površina komponenti djeluje poput jedra.","Teret uvijek podignite više kako bi vjetar imao manji učinak.","Zamijenite remenke tanjima.","Procijenite vjetar i operativna ograničenja i prilagodite podizanje ako je potrebno.","Vjetar može generirati značajne dodatne sile i gibanja njihala, posebno kod opterećenja velikih površina."],"k2-ortswechsel":["Što je važno kod premještanja pokretne dizalice na novu lokaciju?","Uvjeti podloge i podloge se mijenjaju.","Prije ponovnog podizanja tereta provjerite mjesto postolja i oslonac.","Primijenite postavke s prethodne lokacije bez provjere.","Neka oslonac bude ponovno podešen tijekom podizanja.","Svako mjesto postavljanja može imati različite uvjete opterećenja tla i potpore."],"k2-betriebsbereich":["Dizalica bi trebala raditi preko ulice. Što treba razjasniti?","Treće osobe mogu ući u opasno područje.","Cestu osigurajte samo sirenom upozorenja.","Obavezna blokada, glasanje i mjere zaštite ispred čvorišta.","Podignite teret preko vozila što je brže moguće bez učvršćivanja.","Sigurno upravljanje prometom sprječava nepotreban rizik za treće strane od tereta i pomicanja dizalice."],"k2-hochheben":["Nakon probnog dizanja teret očito visi nakrivljeno. Što je ispravno?","Fokus je očito bio pogrešno procijenjen.","Nastavite s podizanjem kako bi se neravnoteža ispravila.","Neka jedna osoba povuče nagnuti teret.","Spustite teret na sigurno i ponovno provjerite priključak i težište.","Probno podizanje se koristi za otkrivanje nepravilnog pričvršćenja i nestabilnog položaja tereta prije transporta."],"k2-schwebelast":["Možete li ostaviti podignuti teret da visi bez nadzora?","Smjena završava, ali teret je još uvijek na kuki.","Ne, sigurno spustite teret i ispravno učvrstite dizalicu.","Da, ako je dizalica blokirana protiv pomicanja.","Da, sve dok postoji znak upozorenja na tlu.","U principu, viseći teret ne bi trebao biti ostavljen bez nadzora."],"k2-mitnahme":["Kolega se želi voziti na teretu dizalice. Što se primjenjuje?","Teret treba transportirati na višu točku.","Jahanje je dozvoljeno ako kolega nosi kacigu.","Ljudi se ne smiju prevoziti na normalnom teretu niti se na njega pričvršćivati.","Vožnja je uvijek dopuštena sve dok je kolega poznat vozaču dizalice.","Nošenje ljudi zajedno s teretom stvara značajne rizike od pada i prignječenja."],"k2-warnsignal":["Operativni sustav upozorenja na dizalici ne radi. Što je ispravno?","Više nije moguće dati upozorenje prije kretanja.","Zanemarite sustav dok motor radi.","Trajno zamijenite upozorenje dodirom kućišta.","Prijavite grešku važnu za sigurnost i prekinite rad prema uputama.","Potrebni uređaji za upozoravanje moraju biti funkcionalni kako bi ljudi bili pravovremeno zaštićeni."],"k2-schneekante":["Pokretnu dizalicu treba poduprijeti na smrznutom, neravnom tlu. Što se primjenjuje?","Otapanjem tlo može izgubiti svoju nosivost.","Procijenite nosivost i situaciju podrške u stvarnim uvjetima.","Smrznuto tlo uvijek ima nosivost.","Podupirače postavljajte samo na malo kamenje.","Temperatura, vlažnost i struktura podzemlja utječu na nosivost mjesta dizalice."],"k2-laufkatze":["Kolica se kreću prema prepreci. kako se ponašaš","U zoni za vožnju nalazi se objekt.","Polako odgurnite predmet s teretom.","Zaustavite kretanje na vrijeme i sigurno uklonite prepreku.","Vozite pored prepreke povećanom brzinom.","Kretanje dizalice mora biti vođeno tako da ne dođe do sudara s preprekama."],"k2-anschlagaufnahme":["Teret biste trebali podići pomoću neodređene ušice. Što je ispravno?","Ušica je mogla biti namijenjena samo za montažu poklopca.","Svaka ušica je prikladna za puno opterećenje dizalice.","Ušicu opterećuju samo dvije osobe u isto vrijeme.","Prije uporabe provjerite nosivost i prikladnost sidrišne točke.","Nije svaka postojeća ušica stabilna točka pričvršćivanja tereta dizalice."],"l2-seilbruch":["Žičano uže pokazuje nekoliko prekinutih pojedinačnih žica. Što je ispravno?","Lomne točke su u području nosivog užeta.","Nemojte nastaviti koristiti opremu za dizanje i dajte je na stručnu procjenu.","Savijte krajeve žice natrag golim rukama.","Nastavite koristiti uže ako je teret posebno lagan.","Prekidi žice mogu biti kriterij za odbacivanje; Oštećena užad mora biti stručno procijenjena."],"l2-schaekel":["Što je presudno kod korištenja okova?","Okov povezuje remen i teret.","Zamijenite vijak bilo kojim čavlom.","Provjerite odgovarajuću nosivost, neoštećeno stanje i ispravne vijke.","Procijenite nosivost na temelju boje.","Okovi moraju biti odgovarajuće veličine, korišteni do kraja i u predviđenom smjeru utovara."],"l2-tragfaehigkeit":["Što morate uzeti u obzir kada koristite više niti?","Pramenovi idu pod kutom prema okomici.","Jednostavno zbrojite nosivost svake niti po želji.","Teret objesite samo na najlakši pramen.","Uzmite u obzir nosivost cijele vrste sidra i kuta.","Kut nagiba i efektivni broj užadi imaju značajan utjecaj na dopušteno opterećenje."],"l2-schweissnaht":["Može li se improvizirana sidrišna točka zavariti na teret?","Ne postoje odgovarajuće označene točke preuzimanja tereta.","Koristite samo ispravno dizajnirane i odobrene sidrišne točke.","Svaki zavareni šav je dovoljan bez ispitivanja.","Umetnite kuku kroz otvor u limu.","Moraju se dokazati prikladnosti sidrišnih točaka za sile uključene u dizanje."],"l2-einseitig":["Teret je znatno teži s jedne strane. Kako to činiš?","Težište se nalazi izvan geometrijskog središta.","Ostavite sve pramenove iste duljine bez obzira na težište.","Odredite težište i prema tome prilagodite položaj.","Prvo podignite teret na punu visinu podizanja.","Ako je središte gravitacije izvan središta, tereti se mogu neočekivano prevrnuti ili se pojedinačne niti mogu preopteretiti."],"l2-kettenriss":["Što se odnosi na lančanu remen s vidljivim pukotinama?","Postoji pukotina na jednoj od karika lanca.","Označite pukotinu bojom i podignite je nepromijenjenu.","Omotajte kariku žicom i ponovno je upotrijebite.","Odmah skinite lanac i obavijestite odgovornu osobu.","Pukotine u nosivim karikama lanca su oštećenja bitna za sigurnost i zahtijevaju stavljanje izvan pogona."],"l2-lastfuehrung":["Kako nositi veliki teret kada postoji opasnost od rotacije?","Teret se tijekom podizanja može zanjihati u stranu.","Koristite odgovarajuće uređaje za navođenje i sigurnu udaljenost.","Držite teret izravno između ruku tijekom vožnje.","Zakoračite ispod tereta i poravnajte ga odozdo.","Vođenje tereta ne smije izazvati dolazak ruku ili tijela u opasno područje."],"l2-schnueren":["Što je važno kod pričvršćivanja vezica?","Remen se vodi oko komponente.","Pretpostavlja se da je nosivost ista kao kod bilo koje druge vrste sidra.","Pripazite na prikladnost vrste priključka i dopušteno opterećenje prema oznaci.","Povucite remen zajedno do bilo koje mjere bez provjere.","Vrsta nastavka za vezivanje može promijeniti dopuštenu nosivost i mora se pravilno koristiti."],"l2-winkelmesser":["Zašto ne možete zanemariti ravni kut niti?","Dva remena se protežu gotovo vodoravno u odnosu na teret.","Ravni kut automatski čini pramen čvršćim.","Opterećenje je uvijek ravnomjerno raspoređeno bez obzira na kut.","Velike sile užeta mogu premašiti dopuštenu nosivost.","Kako se kut prema vertikali povećava, naprezanja na nitima se povećavaju."],"l2-heisse-last":["Što trebate provjeriti za vruće opterećenje?","Čelični dio nedavno je toplinski obrađen.","Pridržavajte se temperaturnih ograničenja remena i odgovarajućeg odabira.","Svaki tekstilni remen može izdržati sve temperature.","Označavanje nije važno kada je vruće.","Temperatura može utjecati na dopuštenu nosivost remena."],"l2-abstand":["Možete li staviti prste ispod tereta kada ga spuštate?","Teret bi trebao stati na površinu s milimetarskom preciznošću.","Da, ako nosite radne rukavice.","Ne, držite se na udaljenosti i koristite odgovarajuća pomagala.","Da, ako je kretanje dizalice posebno sporo.","Dijelovi tijela između tereta i postolja mogu se zaglaviti."],"l2-verbindung":["Spojna karika lanca remena nije zaključana. Što se primjenjuje?","Nedostaje pričvršćivač.","Koristite zasun bez brave kada nitko ne gleda.","Zalijepite element ljepljivom trakom.","Ne udarajte sve dok pričvršćivač nije ispravno pričvršćen.","Vezni elementi moraju biti osigurani u potpunosti iu skladu s njihovom izvedbom."],"l2-lasthaken":["Što provjeravate kada visite na kuki dizalice?","U kuku treba uvući nekoliko remena.","Osigurajte sigurno prianjanje i prikladnost kuka i ovjesa.","Stavite remen na vrh udice.","Zamijenite bravu kuke vezicom za kabel.","Sila se mora primijeniti kako je predviđeno u određenim područjima."],"l2-fasern":["Traka za podizanje pokazuje ozbiljnu hrapavost i oštećenje vlakana. Što je ispravno?","Potporna vlakna su vidno oštećena.","Pokrijte oštećenje drugim čvorom.","Odvojite traku za podizanje i dajte je provjeriti stručnjaku.","Zatim podignite teret brže.","Oštećena nosiva vlakna mogu znatno smanjiti nosivost trake za podizanje."],"l2-anheben":["Što vrijedi odmah nakon prvog centimetra podizanja?","Teret se upravo podiže sa svoje baze.","Povucite teret do njegove pune visine bez kontrole.","Provjerite pod teretom jesu li remeni zategnuti.","Provjerite položaj zaustavljanja, ravnotežu i ponašanje kretanja.","Kontrolirano probno podizanje čini moguće nestabilnosti vidljivima prije daljnjeg transporta."],"l2-lastgewichte":["Težina tereta nije poznata. Što je ispravno?","Komponenta nema oznaku težine.","Odredite nosivu težinu prije odabira remena.","Procijenite težinu na temelju boje tereta.","Koristite bilo koju remen dvostruke duljine.","Bez poznate ili pouzdano utvrđene težine ne može se sa sigurnošću provjeriti prikladnost priveznica."],"l2-lose-teile":["Na teretu koji treba podići ima labavih alata. sta to radis","Alati bi mogli pasti prilikom podizanja.","Dok vozite, držite alat jednom rukom.","Uklonite ili učinkovito osigurajte labave predmete prije podizanja.","Dižite teret malo brže da ništa ne sklizne.","Labavi predmeti mogu pasti i ugroziti ljude u okolini."],"l2-wind":["U jakim vjetrovima pričvršćen je veliki teret. Što se primjenjuje?","Komponenta nudi vjetru veliku površinu za napad.","Podignite teret bez obzira na njihanje.","Dodatne osobe trebaju izravno držati teret.","Procijenite uvjete vjetra i suzdržite se od dizanja ako situacija nije sigurna.","Snage vjetra mogu utjecati na vođenje tereta i stabilnost tijekom transporta."],"l2-unterlage":["Zašto su odgovarajući dokumenti važni prilikom odvikavanja?","Okrugli teret bi se otkotrljao po zemlji.","Teret čvrsto postavite i osigurajte ga od kotrljanja ako je potrebno.","Ostavite teret da stoji izravno na priveznicama.","Dokumente gurnite ispod tereta tek nakon što su odloženi.","Prikladni oslonci sprječavaju prevrtanje i neželjena pomicanja prilikom spuštanja."],"l2-transportweg":["Što je potrebno uskladiti prije prijevoza tereta?","Teret se pomiče preko nekoliko radnih područja.","Samo očekivano trajanje čvorišta.","Siguran put tereta, komunikacija i potrebne barijere.","Jedna osoba treba pokazati put ispod tereta.","Prijevoz tereta zahtijeva sigurne prometne rute i jasnu koordinaciju."],"l2-schutzschlauch":["Na što treba obratiti pozornost pri korištenju remena sa zaštitnim crijevom?","Traka leži na grubom rubu.","Svaka tanka tkanina zamjenjuje odgovarajuću zaštitu rubova.","Zaštitno crijevo uklanja sve dopuštene granice opterećenja.","Odaberite zaštitnu opremu prema prikladnosti i zahtjevima primjene.","Zaštitna oprema mora odgovarati materijalu, rubu i predviđenom opterećenju."],"l2-reinigung":["Traka za podizanje bila je kontaminirana nepoznatom kemikalijom. Što je ispravno?","Vrpca se više ne može jasno procijeniti.","Prestanite koristiti i profesionalno razjasnite kompatibilnost ili stanje.","Očistite bilo kojim otapalom i odmah nastavite s podizanjem.","Zanemarite kemikaliju dok je traka suha.","Kemikalije mogu utjecati na čvrstoću tekstilnih remena."],"l2-aufhaengung":["Što provjeravate za višestruke niti na karici ovjesa?","Dvije niti su postavljene zajedno u suspenziju.","Pramen se po želji može uvući u vrh kuke.","Svi spojni elementi moraju biti prikladni i raspoređeni kako je predviđeno.","Za mala opterećenja može se koristiti prsten s pukotinom.","Granični i spojni elementi moraju biti nosivi i pravilno raspoređeni."],"l2-einweiserrolle":["Što vrijedi ako napadač i kranist nemaju vidnu liniju?","Nosač blokira pogled na točku ispuštanja.","Koordinirati pozivanjem više osoba bez odgovornosti.","Premjestite teret na temelju buke bez instrukcija.","Organizirajte jasnu, sigurnu komunikaciju i zaustavite je ako je nejasna.","Nedostatak vidljivosti mora se nadoknaditi učinkovitom koordinacijom i sigurnom komunikacijom."],"l2-ausserbetrieb":["Oštećena remen je sređena. Što je još važno?","Ostaje slobodno dostupan uz resurse spremne za korištenje.","Osigurajte od daljnje slučajne uporabe i obavijestite odgovornu osobu.","Vratite proizvod neoznačen na zalihu.","Ponovno ga koristite samo kada nosite posebno lagan teret.","Odbačene priveznice moraju biti pouzdano zaštićene prije daljnje uporabe."],"b2-schwenkradius":["Zašto je stražnji polumjer zakretanja bagera kritičan?","Rep se kreće preko ograničenog radnog područja.","Treće osobe mogu biti zahvaćene nadgradnjom koja se ljulja.","Polumjer zakretanja nema utjecaja na ljude pored stroja.","Stražnja se uvijek pomiče samo u smjeru vožnje.","Prilikom zakretanja, opasno područje nastaje i iza stroja."],"b2-verkehrseinweiser":["Kako se osigurava vožnja kada je vidljivost zaklonjena?","Bager mora manevrirati iza prepreke.","Vozite bez da vidite signale signalizatora.","Ako je potrebno, organizirajte odgovarajuće upute uz jasnu komunikaciju.","Osigurajte vožnju unatrag samo jednim trubljenjem.","Zbunjujuće rute zahtijevaju učinkovite mjere za sprječavanje sudara i zarobljavanja."],"b2-standplatz":["Što se odnosi na postolje bagera na kosini?","Pod je nagnut i može biti sklizak.","Stroj se može produžiti koliko želi na bilo kojem nagibu.","Uvijek postavite bager na rahli sloj zemlje.","Prije uporabe provjerite stabilnost i radne granice stroja.","Nagib padine i podtlo imaju značajan utjecaj na stabilnost."],"b2-oberleitung":["Zašto je potrebno planirati udaljenost nosača od dalekovoda?","Grana se može približiti sajli kada se okreće.","Električni bljesak je također moguć bez izravnog kontakta.","Samo žlica može provoditi struju, a ne grana.","Sa suhim tlom svaka je udaljenost automatski sigurna.","Ograničenja uporabe i zaštitne udaljenosti moraju se razjasniti prije pristupa električnim sustavima."],"b2-fremdperson":["Prolaznik ulazi na gradilište u prostor za paniranje. Što je ispravno?","Osoba iznenada stoji blizu žlice bagera.","Podignite lopatu i zamahnite njome iznad osobe.","Odmah zaustavite kretanje i raščistite područje.","Samo nastavite promatrati osobu s bočnog prozora.","Ljudi u opasnom području ne smiju biti ugroženi radnim pokretima."],"b2-parkstellung":["Kako se osigurava stroj za zemljane radove nakon završetka radova?","Bager ostaje bez nadzora na gradilištu.","Ostavite žlicu u razini glave.","Neka motor radi bez nadzora.","Odložite radnu opremu, osigurajte stroj i spriječite neovlaštenu uporabu.","Ispravno parkiranje smanjuje slučajno kretanje i neovlašteni pristup."],"b2-eigenlast":["Zašto su ograničenja opreme presudna pri dizanju bagerom?","Teški teret treba podići na granu.","U protivnom može doći do prekoračenja stabilnosti i dopuštene nosivosti.","Svaki stroj može podići bilo koji teret sve dok žlica stane.","Samo duljina užeta za remen određuje rizik.","Podaci o podizanju i nosivosti ovise o opremi i situaciji primjene."],"b2-untergrundhohlraum":["Pod iznad starog podruma mogao bi biti šupalj. sta to radis","Trebali biste odvesti bager u to područje.","Prijeđite mjesto s maksimalnim zamahom.","Razjasnite nosivost i moguće šupljine prije vožnje.","Jednostavno stavite težak teret na površinu.","Šupljine se mogu urušiti pod težinom stroja i uzrokovati pad stroja."],"b2-feuchtigkeit":["Nakon jake kiše nasip postaje mekan. Što je ispravno?","Uz rub nasipa radi bager.","Pomaknite stroj bliže rubu kako biste povećali doseg.","Zanemarite promjene do kraja smjene.","Ponovno procijenite uvjete tla i stabilnosti.","Prodor vlage može promijeniti nosivost i stabilnost nasipa."],"b2-bodenprobe":["Zašto se planovi cjevovoda moraju provjeriti prije iskopa?","Kabeli bi mogli prolaziti ispod planiranog iskopa.","Tako da se linije mogu identificirati i mogu se planirati odgovarajuće sigurnosne mjere.","Tako da se iskapanje može izvesti brže, neovisno o sustavima trećih strana.","Budući da se strojevi nikada ne smiju koristiti u blizini kabela.","Podzemni opskrbni vodovi zahtijevaju pouzdano razjašnjenje lokacije prije radova na iskopima."],"b2-maschinenzugang":["Što vrijedi pri ulasku i izlasku iz stroja za zemljane radove?","Stroj je na neravnom terenu.","Izvucite hidraulički vod iz kabine.","Koristite predviđene stepenice i osigurajte siguran oslonac.","Skočite na okretnu ruku dok stroj radi.","Sigurni usponi i prikladne točke za zaustavljanje smanjuju rizik od pada i prignječenja."],"b2-kupplung":["Kako provjeriti novi rovokopač nakon ugradnje?","Žlica je spojena preko brze spojnice.","Žlicu procjenjujte samo vizualno s veće udaljenosti.","Zakoračite izravno ispod podignute žlice.","Osigurajte ispravno zaključavanje i propisane korake upravljanja.","Priključci koji nisu ispravno zaključani mogu se olabaviti i ugroziti ljude."],"b2-hydraulikwartung":["Zašto se hidraulični vodovi ne smiju otvarati pod pritiskom?","Potrebno je zamijeniti crijevo.","Tekućina koja curi može uzrokovati ozbiljne ozljede zbog visokog tlaka.","Tlak uvijek sprječava istjecanje ulja.","Otvorena linija može se sigurno provjeriti rukama.","Tekućina pod visokim pritiskom može prodrijeti u tkivo i zahtijeva sigurno rasterećenje pritiska."],"b2-fahrweg":["Morate voziti preko privremenog građevinskog mosta. Što provjeravaš?","Most je projektiran samo za određena opterećenja.","Odgovara li boja mosta stroju.","Nosivost i prikladnost za težinu i dimenzije stroja.","Samo da li je po mostu već provozao lagani auto.","Privremeni objekti smiju se koristiti samo u okviru dokazane nosivosti."],"b2-baggertransport":["Što je važno pri transportu bagera na niskom utovarivaču?","Stroj se odvozi na sljedeće gradilište.","Dopustite radnoj opremi da labavo strši preko ruba.","Držite vrata kabine otvorena tijekom vožnje.","Osigurajte stroj u skladu s transportnim specifikacijama i provjerite opremu za utovar.","Transportne brave i prikladni uređaji za utovar sprječavaju klizanje i pad."],"b2-schaufelfuellung":["Zašto utovarivač na kotačima ne smije voziti brzo s visoko podignutom žlicom?","Teret je težak i tlo je neravno.","Visoko težište može povećati rizik od prevrtanja i problema s vidljivošću.","Žlica se automatski stabilizira pri velikim brzinama.","Visina lopate nije bitna za stabilnost.","Povišeno težište obično pogoršava stabilnost tijekom vožnje i skretanja."],"b2-fussgaenger":["Kako se ponašate kada manevrirate pored pješaka?","Pristup gradilištu također je pješački.","Koristite lopatu da usmjerite pješake u stranu.","Vozite samo kada je područje sigurno slobodno i upravljivo.","Samo jednom zatrubite i vozite polako bez vidljivosti.","Promet vozila i putnika mora biti učinkovito odvojen ili sigurno koordiniran."],"b2-ueberlastwarnung":["Prilikom podizanja stroj javlja preopterećenje. sta to radis","Podignuti teret doseže dopuštene granice.","Isključite upozorenje i nastavite ga podizati nepromijenjeno.","Naglo zategnite teret dok stroj radi.","Zaustavite opasne pokrete i sigurno ispravite situaciju tereta.","Upozorenja o preopterećenju ukazuju na moguće prekoračenje ograničenja i rizike stabilnosti."],"b2-wasserleitung":["Tijekom kopanja otkrivena je nepoznata cijev. Što se primjenjuje?","Linija nije prikazana u građevinskim planovima.","Prestanite s radom na zahvaćenom području i neka stručna osoba identificira liniju.","Pokušajte pomaknuti uže lopatom bagera.","Nastavite kopati izravno ispod linije bez provjere.","Nepoznati vodovi mogu uzrokovati električne, plinske ili vodene opasnosti."],"b2-hangefahrt":["Kako voziti bager na strmoj padini?","Planirana ruta vodi uz padinu.","Vozite preko nagiba bez obzira na ograničenja proizvođača.","Pridržavajte se dopuštenog nagiba i propisanog stila vožnje stroja.","Zakrenite granu daleko prema van kako biste uravnotežili vozilo.","Dopušteni nagib ovisi o stroju, površini i podacima proizvođača."],"b2-schlechtebeleuchtung":["Prilikom rada u tamnoj jami vidljivost je nedovoljna. Što je ispravno?","Jedva možete vidjeti ljude i prepreke.","Povećajte brzinu kopanja kako biste brzo dovršili operaciju.","Ne koristite svjetla dok motor radi.","Prekinite s radom dok opasna područja ne budu dovoljno vidljiva.","Za kontrolirano kretanje stroja potrebna je sigurna vidljivost područja vožnje i rada."],"b2-kettenverschleiss":["Prilikom dnevne kontrole uočava se oštećena gusjenica. sta to radis","Lančana veza pokazuje jasnu štetu.","Nemojte nastaviti nekontrolirano koristiti stroj i prijavite bilo kakvu štetu.","Nastavite voziti velikom brzinom tako da se lanac ispravi.","Nastavite s radom samo na mekom tlu bez provjere.","Oštećenje pogona može narušiti upravljivost i stabilnost."],"b2-ladearbeiten":["Bagerom utovariš kamion. Što je važno?","Vozač kamiona ostaje blizu prostora za utovar.","Zanjihajte kantu preko nezaštićene vozačeve kabine.","Spriječiti boravak ljudi u opasnom području i koordinirati procese.","Započnite utovar bez komunikacije s vozačem.","Prilikom utovara postoji opasnost od pada materijala i njihanja."],"b2-arbeitsunterbrechung":["Prekinuo si radove na iskapanju zbog sastanka. Što se primjenjuje?","Stroj bi trebao stajati nekoliko minuta bez upotrebe.","Ostavite podignutu lopatu kao oznaku.","Ostavite stroj bez nadzora s uključenim vučnim pogonom.","Stroj odložite na sigurno i osigurajte ga od nenamjerne uporabe.","Čak i kratki prekidi zahtijevaju sigurno stanje stroja."],"b2-rollmaterial":["Rasuti materijal može pasti prilikom transporta utovarivačem na kotačima. Što je ispravno?","Utovarivač vozi blizu zaposlenika.","Sigurno pokupite teret i odaberite siguran stil vožnje s prikladnim položajem lopate.","Podignite lopatu što je više moguće tako da okolno područje ima jasan pregled.","Podignite teret bez ograničenja punjenja kante.","Rasuti teret, visoko postavljene žlice i loša vidljivost mogu ugroziti ljude i promet."]};
